function pb.model(Zr,as,bs)
local cs=tostring(Zr)..DLe[2416]..tostring(bs and bs.atk)..DLe[2416]..tostring(bs and bs.cd)
local ds=pb._model[cs]
if ds~=nil then
return ds or nil
end
local es,fs={},false
local gs=math.max(0.3,tonumber(bs and bs.cd)or 2)
local hs=math.min(1,(tonumber(as and as.n)or 1)/4)
local js,ks=pcall(pb.guess,Zr)
local ls,ms={},{}
for ns,ps in ipairs(js and type(ks)==DLe[2274]and ks or{})do
if ps.hand then
ls[ps.pid]=true
end
ms[ps.pid]=ps.nums
end
for qs,rs in pairs(pb.rules(Zr))do
if not ls[qs]then
local ss={}
for ts,us in pairs(type(ms[qs])==DLe[2274]and ms[qs]or{})do
ss[ts]=us
end
for vs,ws in pairs(type(rs.nums)==DLe[2274]and rs.nums or{})do
ss[vs]=ws
end
local xs=rs.trigger~=nil and tostring(rs.trigger):find(DLe[2692],1,true)~=nil
if rs.family==DLe[2474]then
local ys=(xs and pb.ABILITY_UPTIME or 1)*(rs.who==DLe[2542]and pb.RANGE_SHARE or 1)
local zs=es.aura or{typed={}}
for As,Bs in pairs(type(ss.typed)==DLe[2274]and ss.typed or{})do
zs.typed[As]=math.max(zs.typed[As]or 0,(tonumber(Bs)or 0)*ys)
end
local Cs=tonumber(ss.dmgMax)or tonumber(ss.dmg)
if Cs then
zs.dmg=math.max(zs.dmg or 0,Cs*ys)
end
if ss.crit then
zs.crit=math.max(zs.crit or 0,(tonumber(ss.crit)or 0)*ys)
end
es.aura,fs=zs,true
elseif rs.family==DLe[2471]then
local Ds=pb.KW[tostring(rs.keyword or DLe[1193])]
local Es=tonumber(ss.chance)or 1
local Fs=tonumber(ss.secsSeen)or tonumber(ss.secs)or 5
local Gs=ss.keep or ss.keepSeen
local Hs=Gs and math.min(1,Es*4)or math.min(1,Fs*Es/gs)
if xs then
Hs=math.min(Hs,Fs/60)
end
if Ds and Ds.kind==DLe[2461]and not(type(ss.shred)==DLe[2274])then
local Is=tonumber(ss.amp)
local Js=as and((type(as.ampTypes)==DLe[2274]and as.ampTypes[Ds.dtype])or(tonumber(as.amp)or 0)>0)
if Is and Is>0 and not Js then
es.fx,fs=(es.fx or 0)+Is*V.TYPED_AMP_SHARE*Hs*hs,true
end
elseif Ds and(Ds.kind==DLe[2409]or Ds.kind==DLe[2469])then
if not(as and((tonumber(as.stun)or 0)>0 or(tonumber(as.slowTime)or 0)>0))then
es.stun=(Ds.kind==DLe[2469]and 0.5 or 1)*Fs
if ss.slow then
es.slowP,es.slowT=tonumber(ss.slow),Fs
end
fs=true
end
elseif Ds and Ds.kind==DLe[2411]then
if not(as and(tonumber(as.slowTime)or 0)>0)then
es.slowP,es.slowT,fs=tonumber(ss.slow)or tonumber(ss.slowSeen)or 0.3,Fs,true
end
elseif Ds and Ds.kind==DLe[2468]then
local Ks=tonumber(ss.dot)or 0
if Ks>0 and(tonumber(as and as.dot)or 0)<Ks*0.5 then
local Ls=math.min(1.5,Ks)*Es
es.dot,fs=(es.dot or 0)+Ls,true
if tostring(rs.keyword)==DLe[2116]then
es.burnDot=(es.burnDot or 0)+Ls
end
end
end
if type(ss.ampFrom)==DLe[2274]and tostring(ss.ampFrom.kind)==DLe[2116]and(tonumber(ss.ampFrom.amp)or 0)>0 then
local Ms=(type(ss.secsBy)==DLe[2274]and#ss.secsBy>0)and ss.secsBy or{tonumber(ss.secsSeen)or tonumber(ss.secs)or 5}
es.flames,fs={amp=tonumber(ss.ampFrom.amp),secs=Ms},true
end
elseif rs.family==DLe[2528]then
es.exec,fs=tonumber(ss.below)or 0.25,true
end
end
end
pb._model[cs]=fs and es or false
return fs and es or nil
end
