end
end
local fE={}
for gE,hE in pairs(aE)do
fE[hE]=true
end
local iE={}
for jE,kE in ipairs(WD)do
if not fE[kE]and not kE.worn and kE.uuid~=_D and kE.tier<4 then
table.insert(iE,kE)
end
end
table.sort(iE,function(lE,mE)
