function mb.weatherStrength(BE)
local CE=mb.fx(BE)
local DE=CE.dmg/CE.cd/CE.hp/CE.speed*(1+(CE.range-1)/2)
for EE,FE in pairs(CE.kinds)do
DE=DE*(1+bb.rogueShare(EE)*FE)
end
if CE.ice>0 then
local GE=bb.rogueShare(DLe[2425])
DE=DE*(GE+(1-GE)/(1-CE.ice+CE.ice/gb.modFactor(DLe[2833])))
end
if CE.fly>0 then
DE=DE*(1-CE.fly*0.5)
end
if CE.noCC then
DE=DE*0.95
end
if CE.shroud then
DE=DE*0.9
end
if CE.zap then
DE=DE*0.85
end
return DE/mb.weatherK(BE)
end
mb.WEATHER_K_MIN,mb.WEATHER_K_MAX,mb.WEATHER_K_RUNS=0.5,4,10
function mb.weatherK(HE)
local IE=HE and type(P.hunt)==DLe[2274]and type(P.hunt.wk)==DLe[2274]and P.hunt.wk[tostring(HE)]or nil
return type(IE)==DLe[2274]and tonumber(IE.k)or 1
