function mb.weatherLearn()
if bb.withOthers or#game:GetService(DLe[1172]):GetPlayers()>1 then
return
end
local JE=bb.huntWeather or mb.weatherNow()
local KE,LE=bb.pred,bb.calRun
if not JE or type(KE)~=DLe[2274]or type(LE)~=DLe[2274]then
return
end
local function ME(NE,OE)
return type(NE)==DLe[2274]and tonumber(NE[OE]or NE[tostring(OE)])or nil
end
local PE={}
for QE=2,bb.wave()do
local RE,SE=ME(LE.alive,QE),ME(KE.aliveAt,QE)
if RE and SE and RE>0 and SE>0 then
table.insert(PE,RE/SE)
end
end
if#PE<3 then
return
end
table.sort(PE)
local TE=PE[math.ceil(#PE/2)]
P.hunt.wk=type(P.hunt.wk)==DLe[2274]and P.hunt.wk or{}
local UE=P.hunt.wk[tostring(JE)]
local VE=math.min(mb.WEATHER_K_RUNS-1,type(UE)==DLe[2274]and tonumber(UE.n)or 0)
local WE=mb.weatherK(JE)
local XE=math.max(1,VE)
local YE=math.exp((XE*math.log(WE)+math.log(WE*TE))/(XE+1))
YE=U.clamp(YE,mb.WEATHER_K_MIN,mb.WEATHER_K_MAX)
bb.wkWas={w=tostring(JE),old=UE}
P.hunt.wk[tostring(JE)]={k=YE,n=(type(UE)==DLe[2274]and tonumber(UE.n)or 0)+1,at=os.time()}
F.log(1,DLe[2834],string.format(DLe[2835],tostring(JE),TE,tostring(JE),YE,WE,P.hunt.wk[tostring(JE)].n))
end
function mb.cardGems(ZE,_E)
