function kb.relicWorth(Jfb,Kfb)
local Lfb=Kfb._unique_item_data and Kfb._unique_item_data._unique_relic_data
if not Lfb then
return 0
end
local Mfb=N.Items[Kfb.item_id]or{}
local Nfb,Ofb=V.types(Jfb.unit_id)
if Mfb.main_damage_type and Mfb.main_damage_type~=DLe[2977]and Mfb.main_damage_type~=Ofb then
return 0
end
local Pfb,Qfb=0,0
for Rfb,Sfb in pairs(Lfb._core_damage_type_buffs or{})do
if Nfb[Sfb.damage_type]then
Pfb=Pfb+(tonumber(Sfb.mul)or 0)+(tonumber(Sfb.add_upg)or 0)*0.01+(tonumber(Sfb.pen)or 0)*0.001
Qfb=Qfb+(tonumber(Sfb.crit)or 0)
end
end
Pfb=Pfb+Qfb*0.5
local Tfb=V.rows(Jfb.unit_id)
local Ufb=Tfb and Tfb[Tfb.max]
local Vfb=(Ufb and tonumber(Ufb.cd)or 0)*V.mult(Jfb,DLe[2725])
for Wfb,Xfb in pairs(Lfb._unique_relic_effects or{})do
local Yfb=type(Xfb.params)==DLe[2274]and Xfb.params or{}
if Xfb.id==DLe[3382]then
local Zfb=math.min(1,(tonumber(Yfb.extra_damage)or 0)*Vfb/math.max(1,tonumber(Yfb.time_interval)or 40))
local _fb=V.DRONES and V.DRONES[Jfb.unit_id]
if _fb and _fb.late and Vfb>0 then
local agb=1/Vfb
Zfb=Zfb*agb/(agb+(tonumber(_fb.max)or 0)*(tonumber(_fb.late.dmg)or 0)*(tonumber(_fb.hits)or 1)/math.max(0.1,tonumber(_fb.late.cd)or 4))
end
Pfb=Pfb+Zfb
elseif Xfb.id==DLe[3383]then
Pfb=Pfb+(tonumber(Yfb.dmg_buff)or 0)*0.25
elseif Xfb.id==DLe[3384]then
Pfb=Pfb+(tonumber(Yfb.dmg_buff)or 0)*Qfb
elseif Xfb.id==DLe[3385]then
if Nfb.magic then
Pfb=0
else
Pfb=Pfb+(tonumber(Yfb.dmg_buff)or 0)*0.3
end
elseif Xfb.id==DLe[3386]then
if Nfb.water_damage then
Pfb=Pfb+0.05
end
elseif Xfb.id==DLe[2426]then
local bgb=tonumber(Yfb.duration_buff)or tonumber(type(Xfb.static_params)==DLe[2274]and Xfb.static_params.duration_buff)or 2
local cgb,dgb=pcall(V.attackInfo,Ufb and Ufb.atk,Ufb and Ufb.range)
local egb,fgb=cgb and tonumber(dgb.burn)or 0,cgb and tonumber(dgb.dot)or 0
if egb<=0 then
local ggb,hgb=pcall(pb.model,Jfb.unit_id,cgb and dgb or nil,Ufb)
if ggb and type(hgb)==DLe[2274]and(tonumber(hgb.burnDot)or 0)>0 then
egb,fgb=hgb.burnDot,fgb+(tonumber(hgb.dot)or 0)
end
end
Pfb=Pfb+egb*math.max(0,bgb-1)/(1+fgb)
end
end
return Pfb
end
function kb.relicPlan()
local igb=N.session()
if not igb then
return nil
end
local jgb=igb.inventory and igb.inventory.inventory_profile_data or{}
local kgb={}
for lgb,mgb in ipairs(jgb.unique_items or{})do
if type(mgb)==DLe[2274]and mgb.uuid and(N.Items[mgb.item_id]or{}).item_group==DLe[3318]then
table.insert(kgb,mgb)
end
end
local ngb={}
for ogb,pgb in ipairs(V.equipped())do
local qgb=pgb.data and pgb.data.rarity
if not V.isFarm(pgb.id)and(qgb==DLe[2864]or qgb==DLe[2865]or qgb==DLe[3380]or qgb==DLe[3387])then
local rgb=kb.share(pgb.id)
if not P.str.share[pgb.id]then
rgb=math.min(rgb,0.15)
end
local sgb={}
for tgb,ugb in ipairs(kgb)do
local vgb=kb.relicWorth(pgb.u,ugb)*rgb*100
if vgb>0.01 then
table.insert(sgb,{it=ugb,w=vgb})
end
end
table.sort(sgb,function(wgb,xgb)
if wgb.w~=xgb.w then
return wgb.w>xgb.w
end
return wgb.it.uuid<xgb.it.uuid
end)
local ygb,zgb={},{}
for Agb,Bgb in ipairs(sgb)do
local Cgb=zgb[Bgb.it.item_id]or 0
if#ygb<6 and Cgb<((N.Items[Bgb.it.item_id]or{}).unique_equip and 1 or 2)then
zgb[Bgb.it.item_id]=Cgb+1
table.insert(ygb,Bgb)
end
end
if pgb.u._equipped_relic then
local Dgb=false
for Egb,Fgb in ipairs(ygb)do
if Fgb.it.uuid==pgb.u._equipped_relic then
Dgb=true
end
end
local Ggb=not Dgb and igb.inventory:get_item_by_uuid(pgb.u._equipped_relic)
if Ggb then
table.insert(ygb,{it=Ggb,w=kb.relicWorth(pgb.u,Ggb)*rgb*100})
end
end
table.insert(ngb,{e=pgb,share=rgb,opts=ygb})
end
end
local Hgb,Igb={},-1
local Jgb,Kgb,Lgb={},{},{}
local function Mgb(Ngb,Ogb)
if Ngb> #ngb then
if Ogb>Igb then
Igb=Ogb
Hgb=table.clone(Jgb)
end
