end
local Pgb=ngb[Ngb]
Jgb[Pgb.e.uuid]=nil
Mgb(Ngb+1,Ogb)
for Qgb,Rgb in ipairs(Pgb.opts)do
local Sgb=(N.Items[Rgb.it.item_id]or{}).unique_equip
if not Kgb[Rgb.it.uuid]and not(Sgb and Lgb[Rgb.it.item_id])then
Kgb[Rgb.it.uuid]=true
if Sgb then
Lgb[Rgb.it.item_id]=true
end
Jgb[Pgb.e.uuid]=Rgb.it.uuid
Mgb(Ngb+1,Ogb+Rgb.w+(Rgb.it.uuid==Pgb.e.u._equipped_relic and 0.01 or 0))
Jgb[Pgb.e.uuid]=nil
Kgb[Rgb.it.uuid]=nil
