local Zhb=Vhb.collection:get_unit_by_uuid(Yhb)
if Zhb then
Whb=Whb+math.max(0,kb.xpFor(Zhb.unit_id,kb.cap(Zhb))-(tonumber(Zhb.xp)or 0))
end
end
return Whb
end
function kb.plan()
local aib=N.session()
if not aib then
return{}
end
local bib={}
local cib=kb.core()
local dib=kb.foodHeld()
local eib=0
for fib,gib in ipairs(dib)do
eib=eib+gib.n*gib.xp
end
for hib,iib in ipairs(cib)do
local jib=aib.collection:get_unit_by_uuid(iib)
if jib then
local kib,lib=jib.unit_id,V.name(jib.unit_id)
if O.teamXp and eib>0 then
local mib,nib=kb.gainXp(jib,eib)
local oib,pib=kb.gainXp(jib,500000)
local qib=pib>0 and oib/pib*nib or 0
if nib>0 and qib>0 then
local rib=kb.feedPlan(jib)
local sib,tib=kb.level(jib),kb.level({unit_id=kib,xp=(tonumber(jib.xp)or 0)+nib})
table.insert(bib,{kind=DLe[3399],uuid=iib,name=lib,gain=qib,add=nib,planned=rib.planned,items=rib.n,lvl0=sib,lvl1=kb.level({unit_id=kib,xp=(tonumber(jib.xp)or 0)+(rib.planned>0 and rib.planned or nib)}),text=string.format(DLe[3400],lib,U.fmt(nib),tib>sib and string.format(DLe[3401],sib,tib)or string.format(DLe[3402],sib),qib)})
end
end
end
end
table.sort(bib,function(uib,vib)
if uib.gain~=vib.gain then
return uib.gain>vib.gain
end
return uib.text<vib.text
end)
for wib in pairs(V._mult)do
if type(wib)==DLe[1179]and wib:sub(1,5)==DLe[3377]then
V._mult[wib]=nil
end
end
P.str.acts,P.str.actsAt={},os.time()
for xib=1,math.min(12,#bib)do
local yib=bib[xib]
table.insert(P.str.acts,{kind=yib.kind,uuid=yib.uuid,name=yib.name,gain=yib.gain,text=yib.text,blocked=yib.blocked,add=yib.add,planned=yib.planned,items=yib.items,lvl0=yib.lvl0,lvl1=yib.lvl1})
end
return bib
end
function kb.xpRate()
local zib=N.session()
if not zib then
return 0
end
local Aib=0
for Bib,Cib in ipairs(kb.core())do
local Dib=zib.collection:get_unit_by_uuid(Cib)
if Dib then
local Eib,Fib=kb.gainXp(Dib,500000)
if Fib>0 then
Aib=math.max(Aib,Eib/Fib)
end
end
end
local Gib=Aib*(O.strengthValue or 300)
if(tonumber(N.cur(DLe[2349]))or 0)>(O.xpGoldFloor or 100000)then
Gib=math.min(Gib,(N.GOLD_VALUE or 0.02)/14)
end
return Gib
end
function kb.xpGuess(Hib)
local Iib=Hib.level and N.Levels[Hib.level]
if not Iib then
return 0
end
local Jib=math.min(9,tonumber(Iib.story_world_rank)or tonumber(Hib.rank)or 9)
local Kib=tonumber(Iib.story_level_rank)or 6
local Lib=(Hib.kind==DLe[2323]and 1.5 or 1)*(Jib>5 and 2 or 1)
local Mib=2.1564^(Jib-1)*(40+10*Kib)/Lib
if Hib.kind==DLe[2299]then
Mib=3*30*2.1564^(Jib-1)/Lib
end
local Nib=Jib>=9 and 0.3 or(Jib>=7 and 0.5 or 1)
return Mib*Nib*6
end
function kb.modeBonus(Oib)
if not(O.team and O.teamXp)or Oib.kind==DLe[2300]or Oib.kind==DLe[2297]then
return 0
end
local Pib=kb._xpRate and os.time()-(kb._xpRateAt or 0)<300 and kb._xpRate or nil
if not Pib then
Pib=kb.xpRate()
kb._xpRate,kb._xpRateAt=Pib,os.time()
end
if Pib<=0 then
return 0
end
local Qib=P.modes and P.modes[Oib.key]
local Rib=tonumber(Qib and Qib.xp)or kb.xpGuess(Oib)
local Sib=Rib*Pib
if Sib<1 then
return 0
end
return Sib,string.format(DLe[3403],U.fmt(Rib),math.floor(Sib+0.5))
end
function kb.xpSettle()
local Tib=P.lastRun
if not(Tib and type(Tib.xp0)==DLe[2274]and Tib.key)then
return
end
local Uib=N.session()
if not Uib then
return
end
local Vib,Wib=0,0
for Xib,Yib in pairs(Tib.xp0)do
local Zib=Uib.collection:get_unit_by_uuid(Xib)
if Zib then
Vib=Vib+math.max(0,(tonumber(Zib.xp)or 0)-(tonumber(Yib)or 0))
Wib=Wib+1
end
end
P.lastRun=nil
if Wib==0 then
return
end
local _ib=W.rec(Tib.key)
_ib.xp=_ib.xp and(_ib.xp+(Vib-_ib.xp)*0.3)or Vib
if Vib>0 then
F.log(2,kb.LOG,string.format(DLe[3404],Tib.key,U.fmt(Vib)))
