function kb.feedPlan(bjb)
local cjb=V.trait(bjb)
local djb=cjb==DLe[3405]and 1.5 or 1
local ejb=math.max(0,kb.xpFor(bjb.unit_id,kb.cap(bjb))-(tonumber(bjb.xp)or 0))
local fjb,gjb,hjb={},0,0
for ijb,jjb in ipairs(kb.foodHeld())do
local kjb=jjb.xp*djb
local ljb=math.min(jjb.n,math.floor((ejb-gjb)/math.max(1,kjb)))
if ljb>0 then
fjb[jjb.id]=ljb
gjb=gjb+ljb*kjb
hjb=hjb+ljb
end
end
return{feed=fjb,planned=gjb,n=hjb}
end
function kb.run(mjb)
local njb=N.session()
local ojb=njb and njb.collection:get_unit_by_uuid(mjb.uuid)
if not ojb then
return
end
if mjb.kind==DLe[3399]then
local pjb=kb.feedPlan(ojb)
local qjb,rjb,sjb=pjb.feed,pjb.planned,pjb.n
if sjb==0 then
P.str.feedNote=mjb.name..DLe[3406]
return
end
local tjb,ujb=tonumber(ojb.xp)or 0,kb.level(ojb)
local vjb,wjb=F.request(DLe[3399],DLe[3407],mjb.uuid,qjb)
local xjb=U.now()
while U.now()-xjb<4 and(tonumber((njb.collection:get_unit_by_uuid(mjb.uuid)or ojb).xp)or 0)<=tjb do
task.wait(0.25)
end
local yjb=njb.collection:get_unit_by_uuid(mjb.uuid)or ojb
local zjb=(tonumber(yjb.xp)or 0)-tjb
if zjb>0 then
local Ajb=kb.level(yjb)
local Bjb=Ajb>ujb and string.format(DLe[3401],ujb,Ajb)or string.format(DLe[3402],ujb)
cb.add(string.format(DLe[3408],sjb,mjb.name),sjb,DLe[3409],string.format(DLe[3410],U.fmt(zjb),Bjb))
kb.note(string.format(DLe[3411],mjb.name,sjb,U.fmt(zjb),Bjb,math.abs(zjb-rjb)>rjb*0.1 and string.format(DLe[3412],U.fmt(rjb))or DLe[1193]))
else
kb.note(string.format(DLe[3413],mjb.name,tostring(vjb and wjb or DLe[2828])))
F.backoff(DLe[3399],600)
end
end
end
