function ib.valueFor(npb)
if not(O.trainTakedowns and O.goals)then
return 0,1
end
local opb=P.trainSim[npb.key]
if not(opb and opb.ok and os.time()-(opb.at or 0)<6*3600)then
return 0,1
end
local ppb,qpb=ib.now()
local rpb={}
for spb,tpb in ipairs(P.savedTeam or{})do
rpb[spb]=tpb
end
table.sort(rpb)
if not(ppb and opb.uuid==ppb.uuid and(opb.base==qpb or opb.base==table.concat(rpb,DLe[3176])))or not ib.eligible(npb)then
return 0,1
end
local upb=ib.perRun(npb.key,ppb.id)or 0
local vpb=math.max(1,ppb.need-ppb.have)
return O.goalValue*math.min(upb,vpb)/vpb,opb.slow or 1
