end
local xpb=(P.train.on and P.train.on.base)or ib.team()
for ypb,zpb in ipairs(xpb)do
if zpb==wpb.uuid then
return
end
end
local Apb,Bpb=0,0
for Cpb,Dpb in ipairs(W.lastScored or{})do
if Apb>=3 or Bpb>=2 then
break
end
if ib.eligible(Dpb)then
local Epb=P.trainSim[Dpb.key]
local Fpb=Epb and Epb.uuid==wpb.uuid and os.time()-(Epb.at or 0)<6*3600
local Gpb=ib.plan(Dpb,wpb,xpb)
if not Fpb then
Bpb=Bpb+1
