function ib.bestInfinite()
local Ipb,Jpb
for Kpb,Lpb in ipairs(W.lastScored or{})do
if Lpb.kind==DLe[2299]and ib.eligible(Lpb)then
local Mpb,Npb=P.train.real[Lpb.key],Lpb.rec or W.rec(Lpb.key)
local Opb=(tonumber(Npb.timed)or 0)>0 and Npb.sec/Npb.timed/60 or 0
local Ppb=(Mpb and Mpb.n>0 and Opb>0)and(Mpb.sum/Mpb.n)/Opb or 0
if Ppb<=0 then
Ppb=db.hiveTrainRate(Lpb.key)or 0
end
if Ppb>(Jpb or 0)then
Ipb,Jpb=Lpb,Ppb
end
end
end
return Ipb
end
function ib.ratio()
