else
nqb.out,nqb.tk,nqb.minutes=Gqb.out,Gqb.r.tk or 0,Gqb.r.t/60
nqb.uuids={}
for Nqb,Oqb in ipairs(Gqb.trial)do
table.insert(nqb.uuids,Oqb.uuid)
