F.log(1,DLe[3587],string.format(DLe[3588],dqb.label,V.name(eqb.id),nqb.out and(DLe[3589]..V.name(nqb.out))or DLe[1193],nqb.ok and string.format(DLe[3590],math.floor((ib.perRun(dqb.key,eqb.id)or 0)+0.5),eqb.what,nqb.minutes,nqb.ownMin)or tostring(nqb.why)))
