sDb.n=(tonumber(sDb.n)or 0)+1
sDb.per=sDb.per and(sDb.per+(rDb-sDb.per)*math.max(0.25,1/sDb.n))or rDb
P.portalPay[qDb]=sDb
end
local tDb,uDb=(N.Items[mDb.item]or{}).name or mDb.item,(N.Items[mDb.portal]or{}).name or mDb.portal
