end
else
local vDb=oDb-(tonumber(mDb.held)or 0)
pDb(DLe[3267]..mDb.portal,math.max(0,vDb))
F.log(1,DLe[3891],string.format(DLe[3908],W.levelName(W.PORTALS[mDb.portal].from),vDb,uDb,oDb,nDb>0 and string.format(DLe[3909],nDb,tDb)or DLe[1193]))
end
W.lastScored=nil
