function ab.relicClash(JDb)
local KDb=N.session()
local LDb={}
for MDb,NDb in ipairs(P.savedTeam or{})do
LDb[NDb]=true
end
local ODb={}
for PDb,QDb in ipairs(JDb)do
local RDb=KDb.collection:get_unit_by_uuid(QDb)
local SDb=RDb and RDb._equipped_relic and KDb.inventory:get_item_by_uuid(RDb._equipped_relic)
if SDb and SDb.item_id and(N.Items[SDb.item_id]or{}).unique_equip then
table.insert(ODb,{uuid=QDb,u=RDb,kind=SDb.item_id,relic=RDb._equipped_relic,k=(LDb[QDb]and 1e12 or 0)+kb.score(RDb)})
end
end
table.sort(ODb,function(TDb,UDb)
if TDb.k~=UDb.k then
return TDb.k>UDb.k
end
return TDb.uuid<UDb.uuid
end)
local VDb={}
for WDb,XDb in ipairs(ODb)do
if VDb[XDb.kind]then
local YDb=(N.Items[XDb.kind]or{}).name or XDb.kind
local ZDb,_Db=F.request(DLe[3912],DLe[3391],XDb.relic)
local aEb=U.now()
while U.now()-aEb<3 and XDb.u._equipped_relic==XDb.relic do
task.wait(0.25)
end
if XDb.u._equipped_relic~=XDb.relic then
P.relicOff[XDb.uuid]=XDb.relic
F.log(1,DLe[3416],string.format(DLe[3913],V.name(XDb.u.unit_id),YDb,V.name(VDb[XDb.kind])))
else
F.log(1,DLe[3416],string.format(DLe[3914],V.name(XDb.u.unit_id),YDb,tostring(_Db)))
end
else
VDb[XDb.kind]=XDb.u.unit_id
end
end
end
function ab.relicBack()
if O.team and O.teamRelics then
table.clear(P.relicOff)
return
end
local bEb=N.session()
for cEb,dEb in pairs(P.relicOff)do
local eEb=bEb.collection:get_unit_by_uuid(cEb)
local fEb=bEb.inventory:get_item_by_uuid(dEb)
local gEb=fEb and fEb._unique_item_data and fEb._unique_item_data._unique_relic_data
if eEb and gEb and not eEb._equipped_relic and not gEb._equipped_unit_uuid and not kb.slotOf(cEb)then
local hEb
for iEb,jEb in ipairs(V.equipped())do
local kEb=jEb.u._equipped_relic and bEb.inventory:get_item_by_uuid(jEb.u._equipped_relic)
if kEb and kEb.item_id==fEb.item_id then
hEb=jEb
end
end
if hEb then
P.str.reequip={uuid=hEb.uuid,slot=hEb.slot}
F.saveNow()
F.request(DLe[2889],DLe[2890],hEb.uuid)
local lEb=U.now()
while U.now()-lEb<4 and kb.slotOf(hEb.uuid)do
task.wait(0.25)
end
end
F.request(DLe[3912],DLe[2821],dEb,{unit_uuid=cEb})
local mEb=U.now()
while U.now()-mEb<3 and eEb._equipped_relic~=dEb do
task.wait(0.25)
end
if hEb then
kb.reequip()
end
F.log(1,DLe[3416],string.format(DLe[3915],V.name(eEb.unit_id),(N.Items[fEb.item_id]or{}).name or tostring(fEb.item_id),eEb._equipped_relic==dEb and DLe[1193]or DLe[3916]))
end
P.relicOff[cEb]=nil
end
end
function ab.equipTeam(nEb,oEb)
local pEb={}
