pEb[rEb.uuid]=true
end
if not P.savedTeam then
local sEb={}
for tEb,uEb in ipairs(V.equipped())do
table.insert(sEb,uEb.uuid)
end
P.savedTeam=sEb
end
local vEb,wEb=pcall(ab.relicClash,nEb)
if not vEb then
F.log(1,DLe[2283],DLe[3917]..tostring(wEb))
end
local xEb={}
for yEb,zEb in ipairs(nEb)do
xEb[zEb]=true
end
local AEb,BEb=false,{}
for CEb=1,4 do
for DEb in pairs(pEb)do
if not xEb[DEb]then
local EEb,FEb=F.request(DLe[2889],DLe[2890],DEb)
table.insert(BEb,string.format(DLe[3918],V.name((N.session().collection:get_unit_by_uuid(DEb)or{}).unit_id or DLe[2525]),tostring(FEb)))
task.wait(0.8)
end
end
for GEb,HEb in ipairs(nEb)do
if not pEb[HEb]then
local IEb
if CEb>2 then
local JEb={}
for KEb,LEb in ipairs(V.equipped())do
JEb[LEb.slot]=true
end
for MEb=1,6 do
if not JEb[MEb]then
IEb=MEb
break
end
end
end
local NEb,OEb
if IEb then
NEb,OEb=F.request(DLe[3414],DLe[3415],HEb,IEb)
else
NEb,OEb=F.request(DLe[3414],DLe[3415],HEb)
end
table.insert(BEb,string.format(DLe[3919],V.name((N.session().collection:get_unit_by_uuid(HEb)or{}).unit_id or DLe[2525]),IEb and(DLe[3920]..IEb)or DLe[1193],tostring(NEb),tostring(OEb)))
task.wait(0.8)
end
end
local PEb=U.now()
while U.now()-PEb<3 and not ib.same(ib.team(),nEb)do
task.wait(0.25)
end
AEb=ib.same(ib.team(),nEb)
if AEb then
break
end
pEb={}
for QEb,REb in ipairs(V.equipped())do
pEb[REb.uuid]=true
end
end
W._sigAt=nil
if AEb then
F.log(1,DLe[3416],DLe[3921].. #nEb..DLe[3922]..tostring(oEb))
else
local SEb={}
for TEb,UEb in ipairs(V.equipped())do
table.insert(SEb,V.name(UEb.id))
end
F.log(1,DLe[3416],DLe[3923]..tostring(oEb)..DLe[3924]..table.concat(SEb,DLe[2398])..DLe[3925]..table.concat(BEb,DLe[2665]))
if not ab.refilling and#V.equipped()<6 then
ab.refilling=true
local VEb,WEb={},{}
for XEb,YEb in ipairs(V.equipped())do
WEb[YEb.uuid]=true
end
for ZEb,_Eb in ipairs(P.savedTeam or{})do
if not WEb[_Eb]and N.session().collection:get_unit_by_uuid(_Eb)then
table.insert(VEb,_Eb)
end
end
local aFb=0
for bFb,cFb in ipairs(VEb)do
if#V.equipped()>=6 then
break
end
F.request(DLe[3414],DLe[3415],cFb)
task.wait(0.8)
local dFb=U.now()
while U.now()-dFb<3 and#V.equipped()<math.min(6,aFb+1+(6- #VEb))do
task.wait(0.25)
end
for eFb,fFb in ipairs(V.equipped())do
if fFb.uuid==cFb then
aFb=aFb+1
end
end
end
local gFb={}
for hFb,iFb in ipairs(V.equipped())do
table.insert(gFb,V.name(iFb.id))
end
F.log(1,DLe[3416],string.format(DLe[3926],aFb,table.concat(gFb,DLe[2398])))
W._sigAt=nil
ab.refilling=nil
end
end
F.saveSoon()
return AEb
