if rFb and rFb.unit_id==jFb.out then
nFb=pFb
end
if rFb and rFb.unit_id==jFb.into then
oFb=true
end
end
local sFb,tFb
for uFb,vFb in pairs(lFb.profile_data.collection.owned_units)do
if vFb.unit_id==jFb.into and(not sFb or(tonumber(vFb.xp)or 0)>tFb)then
sFb,tFb=uFb,tonumber(vFb.xp)or 0
end
end
if oFb or not nFb or not sFb then
P.ownSwap=nil
F.log(1,DLe[3416],string.format(DLe[3927],V.name(jFb.into),V.name(jFb.out),oFb and DLe[3928]or not nFb and DLe[3929]or DLe[3930]))
return F.saveSoon()
end
mFb[nFb]=sFb
local wFb=P.savedTeam
P.savedTeam=nil
if ab.equipTeam(mFb,string.format(DLe[3931],V.name(jFb.into),V.name(jFb.out)))then
P.savedTeam,P.ownSwap=nil,nil
W.lastScored=nil
if F.notify then
F.notify(DLe[3932],string.format(DLe[3933],V.name(jFb.into),V.name(jFb.out)),DLe[3249])
end
else
P.savedTeam=wFb or P.savedTeam
end
F.saveSoon()
end
function ab.restoreTeam()
