ab.LAB={EVERY=3,KINDS={story=true,raid=true,infinite=true},MIN_EVIDENCE=5,AGAIN=3600}
function ab.unitEvidence(CFb)
local DFb=P.learn[CFb]
local EFb=DFb and tonumber(DFb.n)or 0
local FFb=db.hive()
local GFb=FFb and type(FFb.units)==DLe[2274]and FFb.units[CFb]
if type(GFb)==DLe[2274]then
EFb=EFb+(tonumber(GFb.matches)or 0)+(tonumber(GFb.matches3)or 0)
end
return EFb
end
function ab.unitLabSafe(HFb)
if O.unitLab==false or type(HFb)~=DLe[2274]or not ab.LAB.KINDS[HFb.kind]or HFb.first then
return false
end
if P.trial or(P.study and not P.study.done)or(type(P.testTeam)==DLe[2274]and(tonumber(P.testTeam.left)or 0)>0)or(P.train and P.train.on)or ab.partyRole()~=DLe[1199]then
return false
end
local IFb,JFb=pcall(ab.matchOn,HFb)
if IFb and JFb then
return false
end
local KFb=type(P.unitLab)==DLe[2274]and P.unitLab or{}
if KFb.pauseKey==HFb.key and os.time()<(tonumber(KFb.pauseUntil)or 0)then
return false
end
local LFb=W.rec(HFb.key)
local MFb,NFb=tonumber(LFb.runs)or 0,tonumber(LFb.wins)or 0
if HFb.kind==DLe[2299]then
local OFb,PFb=pcall(W.infDaily,N.prof(),HFb.level,W.infReach(HFb.key))
return MFb>=3 and OFb and(tonumber(PFb)or 1)<=0
end
return MFb>=5 and(tonumber(LFb.streak)or 0)==0 and NFb/MFb>=0.9
end
function ab.unitLab(QFb)
if not ab.unitLabSafe(QFb)then
return
end
P.unitLab=type(P.unitLab)==DLe[2274]and P.unitLab or{}
local RFb=P.unitLab
RFb.tried=type(RFb.tried)==DLe[2274]and RFb.tried or{}
RFb.seen=(tonumber(RFb.seen)or 0)+1
if RFb.seen%ab.LAB.EVERY~=0 then
return
end
local SFb=N.session()
local TFb=V.equipped()
if not SFb or#TFb<2 then
return
end
local UFb={}
for VFb,WFb in ipairs(TFb)do
UFb[WFb.uuid]=true
UFb[WFb.id]=true
end
local XFb,YFb,ZFb
for _Fb,aGb in pairs(SFb.profile_data.collection.owned_units)do
local bGb=aGb.unit_id
if not UFb[_Fb]and not UFb[bGb]and N.Units[bGb]and not V.isFarm(bGb)and not V.allyBuff(bGb)and os.time()-(tonumber(RFb.tried[bGb])or 0)>ab.LAB.AGAIN then
local cGb=ab.unitEvidence(bGb)
if cGb<ab.LAB.MIN_EVIDENCE then
local dGb=SFb.collection:get_unit_by_uuid(_Fb)or aGb
local eGb=kb.score(dGb)
if eGb>0 and(not XFb or cGb<YFb or(cGb==YFb and eGb>ZFb))then
XFb,YFb,ZFb={uuid=_Fb,id=bGb,u=dGb},cGb,eGb
end
end
end
end
if not XFb then
return
end
local fGb,gGb
for hGb,iGb in ipairs(TFb)do
if not V.isFarm(iGb.id)and not V.allyBuff(iGb.id)and iGb.uuid~=O.evolveUnit then
local jGb=kb.score(iGb.u)
if not fGb or jGb<gGb then
fGb,gGb=iGb,jGb
end
end
end
if not fGb then
return
end
RFb.tried[XFb.id]=os.time()
local kGb=0
for lGb in pairs(RFb.tried)do
kGb=kGb+1
if kGb>300 then
RFb.tried[lGb]=nil
end
end
local mGb,nGb=gb.levelFor(QFb)
if not mGb then
return
end
local oGb=gb.info(mGb,QFb.key,nGb,QFb.mod or W.ldMod(mGb)or W.levelMod(QFb.level))
local pGb={}
for qGb,rGb in ipairs(TFb)do
table.insert(pGb,rGb.uuid==fGb.uuid and XFb.u or rGb.u)
end
local sGb,tGb=pcall(gb.run,oGb,gb.teamFrom(pGb,oGb.map),{hpMul=1.1})
local uGb=sGb and type(tGb)==DLe[2274]and(tGb.won or(oGb.infinite and(tonumber(tGb.wave)or 0)>=0.8*W.infReach(QFb.key)))
if not uGb then
F.log(2,DLe[3936],string.format(DLe[3937],V.name(XFb.id),QFb.label))
return
end
local vGb={}
for wGb,xGb in ipairs(TFb)do
table.insert(vGb,xGb.uuid==fGb.uuid and XFb.uuid or xGb.uuid)
end
if ab.equipTeam(vGb,DLe[3938]..V.name(XFb.id))then
RFb.now={id=XFb.id,out=fGb.id,key=QFb.key,at=os.time(),ev=YFb}
F.log(1,DLe[3936],string.format(DLe[3939],V.name(XFb.id),V.name(fGb.id),QFb.label,YFb))
F.saveNow()
end
end
function ab.unitLabDone(yGb)
local zGb=P.unitLab
local AGb=type(zGb)==DLe[2274]and zGb.now
if type(AGb)~=DLe[2274]then
return
end
zGb.now,zGb.restore=nil,true
if bb.key~=AGb.key then
return
end
local BGb=bb.lastEff and bb.lastEff[AGb.id]
zGb.runs=(tonumber(zGb.runs)or 0)+1
zGb.done=type(zGb.done)==DLe[2274]and zGb.done or{}
zGb.done[AGb.id]={at=os.time(),eff=BGb,won=yGb and true or false}
zGb.last=AGb.id
