zGb.pauseKey,zGb.pauseUntil=AGb.key,os.time()+3600
end
F.log(1,DLe[3936],string.format(DLe[3940],V.name(AGb.id),yGb and DLe[3060]or DLe[3941],BGb and string.format(DLe[3942],BGb)or DLe[3943]))
end
function ab.unitLabText()
