ab.QUICK_SEARCH=7
function ab.teamFor(IGb,JGb)
if IGb.key==DLe[3035]then
if P.savedTeam then
ab.restoreTeam()
end
return
end
local KGb=N.session()
local LGb=P.testTeam
if LGb and(LGb.left or 0)>0 and LGb.key==IGb.key and type(LGb.uuids)==DLe[2274]then
local MGb=0
for NGb,OGb in ipairs(LGb.uuids)do
if KGb.collection:get_unit_by_uuid(OGb)then
MGb=MGb+1
end
end
if MGb== #LGb.uuids then
if P.train.on then
ib.home()
end
if not ib.same(ib.team(),LGb.uuids)then
ab.equipTeam(LGb.uuids,DLe[3949]..tostring(LGb.label))
end
return
