function eb.upgradeGain(FLb,GLb,HLb,ILb,JLb,KLb)
local LLb,MLb=GLb[HLb],GLb[HLb+1]
local NLb=(LLb.cd>0 and LLb.damage/LLb.cd or 0)
local OLb=(MLb.cd>0 and MLb.damage/MLb.cd or 0)*V.aoe(MLb.atk,MLb.range)/math.max(0.3,V.aoe(LLb.atk,LLb.range))
local PLb=NLb>0 and FLb*(OLb/NLb-1)or(KLb or 0)
local QLb=GLb[HLb+2]
if QLb and HLb+1<GLb.max and QLb.cd>0 and MLb.cd>0 and NLb>0 then
local RLb=FLb*((QLb.damage/QLb.cd)/NLb-1)
local SLb=ILb+QLb.cost*JLb
if RLb/SLb>PLb/ILb then
PLb=PLb+(RLb/SLb*ILb-PLb)*0.5
end
end
local TLb=(MLb.range or 0)>(LLb.range or 0)and(1+((MLb.range-LLb.range)/math.max(1,LLb.range)))or 1
return math.max(0,PLb)*TLb
end
function eb.dpsFor(ULb,VLb)
if VLb<=0 then
return 0
end
local WLb={}
for XLb,YLb in ipairs(ULb)do
if not YLb.farm and not YLb.grif and YLb.gain>0 then
table.insert(WLb,YLb)
end
end
table.sort(WLb,function(ZLb,_Lb)
return ZLb.gain/ZLb.cost>_Lb.gain/_Lb.cost
end)
local aMb,bMb=0,0
for cMb,dMb in ipairs(WLb)do
if VLb<=0 then
break
end
bMb=dMb.gain/dMb.cost
local eMb=math.min(1,VLb/dMb.cost)
aMb=aMb+dMb.gain*eMb
VLb=VLb-dMb.cost*eMb
end
return aMb+math.max(0,VLb)*bMb*0.7
end
function eb.shieldDps(fMb,gMb,hMb,iMb,jMb,kMb,lMb)
if(iMb or 0)<=0 or(fMb or 0)<=0 or(jMb or 0)<=0 then
return fMb or 0
end
gMb,hMb,kMb=math.max(0.3,gMb or 2),math.max(1,hMb or 1),kMb or 1
local mMb=fMb*kMb*gMb/hMb
return jMb*hMb/((iMb/math.max(1,lMb or 1)+math.max(1,jMb/mMb))*gMb)/kMb
end
function eb.shieldGain(nMb,oMb,pMb,qMb,rMb,sMb,tMb,uMb)
local vMb,wMb=V.attackInfo(oMb.atk,oMb.range),V.attackInfo(qMb.atk,qMb.range)
local xMb=eb.shieldDps(nMb,(tonumber(oMb.cd)or 2)*(tMb or 1),vMb.n,rMb,sMb,uMb,vMb.hits)
local yMb=eb.shieldDps(pMb,(tonumber(qMb.cd)or 2)*(tMb or 1),wMb.n,rMb,sMb,uMb,wMb.hits)
local zMb=math.max(0,((tonumber(qMb.range)or 0)-(tonumber(oMb.range)or 0))/math.max(1,tonumber(oMb.range)or 1))
return math.max(0,yMb-xMb)+xMb*zMb
end
function eb.shieldWork(AMb,BMb,CMb,DMb,EMb,FMb,GMb,HMb,IMb)
if(DMb or 0)<=0 then
return 0
end
local JMb=3*DMb*(EMb or 1)/math.max(1,FMb or 20)
if(CMb or 0)>=JMb then
return 0
end
return math.max(1,AMb or 1)*math.max(1,IMb or 1)/math.max(0.3,BMb or 2)*math.min(GMb or 0,HMb or 0)
end
function eb.holdGain(KMb,LMb,MMb,NMb)
if not KMb or(LMb or 0)<=0 then
return 0
end
local OMb,PMb=tonumber(KMb.stun)or 0,tonumber(KMb.slowTime)or 0
if OMb<=0 and PMb<=0 then
return 0
end
local QMb,RMb=OMb>0 and OMb or PMb,OMb>0 and 1 or(tonumber(KMb.slowPct)or 0.3)
local SMb=RMb*QMb/(QMb+(tonumber(KMb.ccCd)or 8))
local TMb=SMb/math.max(0.1,1-SMb)
return LMb*TMb*U.clamp(MMb or 0.5,0,1)*math.min(1,(tonumber(KMb.n)or 1)/2)/(1+(NMb or 0))
end
function eb.bleedGain(UMb,VMb,WMb,XMb)
if(UMb or 0)<=0 then
return 0
end
local YMb=VMb or 0
for ZMb,_Mb in ipairs(WMb or{})do
YMb=math.max(YMb,(tonumber(_Mb.hp)or 0)*0.5)
end
return UMb*YMb*(XMb and 0.5 or 1)
end
function eb.bleedShare(aNb,bNb,cNb,dNb)
if aNb<=0 or not bNb then
return 0
end
if dNb then
return bNb==0 and aNb or aNb/(bNb+1)
end
return cNb<bNb and aNb/(bNb-cNb)or 0
end
function eb.keepsUp(eNb,fNb,gNb,hNb,iNb)
local jNb=eNb.coming
if not(jNb and#jNb>0 and eNb.waveSec)then
return true
end
local kNb=eNb.eff or 1
local lNb=eNb.money-gNb
local mNb=(eNb.teamDps or 0)*(eNb.shieldK or 1)+(hNb or 0)*kNb+eb.dpsFor(fNb,math.max(0,lNb))*kNb
local nNb=(eNb.farmNow or 0)+(iNb or 0)
local oNb=(eNb.roadSec or 130)*U.clamp(eNb.cover or 0.6,0.1,1)
local pNb=eNb.hpAlive or 0
for qNb,rNb in ipairs(jNb)do
pNb=math.max(0,pNb+rNb.hp-mNb*eNb.waveSec)
local sNb=mNb*oNb
if pNb>sNb then
return false,qNb,sNb/math.max(1,pNb)
end
if qNb< #jNb then
mNb=mNb+eb.dpsFor(fNb,(rNb.reward or 0)+nNb)*kNb*(0.85^qNb)
end
end
return true
end
function eb.decide(tNb,uNb)
local vNb=U.clamp(uNb.cover or 0.6,0.1,1)
local wNb=math.max(O.clearSec,0.7*(uNb.roadSec or 50)*vNb)
local xNb=(uNb.clearSec or 0)>wNb
uNb.piling=uNb.piling and xNb
local yNb=uNb.attackers>0 and uNb.pressure<math.min(O.safeReach,vNb*0.75)and not uNb.piling and not xNb
local zNb=uNb.pressure>=math.min(O.dangerReach,vNb*0.9)or(uNb.piling and uNb.enemies>=18)
local ANb,BNb
for CNb,DNb in ipairs(tNb)do
if DNb.farm then
if O.farmUnits and DNb.gain>0 then
DNb.payback=DNb.cost/DNb.gain
if uNb.left-1>=DNb.payback+(uNb.farmSpare or O.farmSpare)and(not ANb or DNb.payback<ANb.payback)then
ANb=DNb
end
end
else
DNb.ratio=DNb.gain/math.max(1,DNb.cost)
if not BNb or DNb.ratio>BNb.ratio then
BNb=DNb
end
end
end
if uNb.leak and uNb.attackers>0 then
local ENb
for FNb,GNb in ipairs(tNb)do
local HNb=not uNb.airLeak or(GNb.e and bb.cardAir(GNb.e.id))
if GNb.place and not GNb.farm and not GNb.idol and not GNb.grif and HNb and GNb.cost<=uNb.money and not(GNb.e and V.allyBuff(GNb.e.id))and(not ENb or GNb.gain>ENb.gain)then
ENb=GNb
end
end
if ENb then
return ENb,string.format(DLe[4082],math.floor(uNb.leak*100))
end
end
local INb=uNb.future<uNb.wantLeft*1.1
local JNb,KNb,LNb=true,nil,nil
if ANb then
JNb,KNb,LNb=eb.keepsUp(uNb,tNb,ANb.cost,0,ANb.gain)
end
local MNb=uNb.coming and not eb.keepsUp(uNb,tNb,0,0,0)
local NNb=false
if bb.random and ANb and not zNb and uNb.attackers>=2 and ANb.payback<=uNb.left/3 then
local ONb=0
for PNb,QNb in ipairs(bb.mine or{})do
if V.isFarm(QNb._stats.id.Value)then
ONb=ONb+1
end
end
NNb=not ANb.place or ONb<4
end
if MNb and uNb.attackers>0 then
zNb=true
end
if zNb and BNb and BNb.grif then
BNb=nil
for RNb,SNb in ipairs(tNb)do
if not SNb.farm and not SNb.grif and(not BNb or SNb.ratio>BNb.ratio)then
BNb=SNb
end
end
end
local TNb=math.max(1,uNb.incomeRate or 20)
local UNb=uNb.waveSec or 20
local function VNb(WNb,XNb,YNb)
local ZNb=math.max(0,(WNb.cost-uNb.money)/TNb)
local _Nb=WNb.gain*math.max(0,YNb-ZNb)
if XNb then
local aOb=math.max(0,uNb.money-WNb.cost)
local bOb=ZNb+math.max(0,(XNb.cost-aOb)/TNb)
_Nb=_Nb+XNb.gain*math.max(0,YNb-bOb)
end
return _Nb
end
local cOb,dOb
if uNb.attackers==0 and BNb then
local eOb=4*UNb
local fOb={}
for gOb,hOb in ipairs(tNb)do
local iOb=type(O.placeFirst)==DLe[2274]and type(hOb.e)==DLe[2274]and table.find(O.placeFirst,hOb.e.id)~=nil
if hOb.place and not hOb.farm and not hOb.grif then
table.insert(fOb,{o=hOb,v=VNb(hOb,nil,eOb)*(iOb and 1e6 or 1),pf=iOb})
end
end
table.sort(fOb,function(jOb,kOb)
return jOb.v>kOb.v
end)
local lOb=uNb.opener and fOb[uNb.opener]and uNb.opener or 1
local mOb=fOb[lOb]and fOb[lOb].o
cOb,dOb=mOb or BNb,lOb>1 and DLe[4083]or((fOb[lOb]and fOb[lOb].pf)and DLe[4084]or DLe[4085])
elseif O.farmFirst and ANb and not zNb and not bb.random then
cOb=ANb
dOb=string.format(DLe[4086],ANb.payback,uNb.left)
elseif ANb and yNb and INb and not zNb and JNb then
cOb=ANb
dOb=string.format(DLe[4087],ANb.payback,uNb.left,uNb.coming and#uNb.coming or 0)
elseif NNb then
cOb=ANb
dOb=string.format(DLe[4088],ANb.payback,uNb.left)
elseif BNb then
cOb=BNb
if MNb then
dOb=string.format(DLe[4089])
elseif zNb then
dOb=string.format(DLe[4090],math.floor(uNb.pressure*100),math.floor(vNb*100))
elseif ANb and not JNb then
dOb=string.format(DLe[4091],KNb or 1,math.floor((LNb or 0)*100))
elseif ANb and xNb then
dOb=string.format(DLe[4092],math.min(999,math.floor(uNb.clearSec)),math.floor(wNb))
elseif ANb and uNb.piling then
dOb=string.format(DLe[4093],uNb.enemies)
