function gb.objective(Gic)
if Gic.kscore then
return(tonumber(Gic.kills)or 0)+Gic.wave*0.01
end
return(Gic.won and 1000 or 0)+Gic.wave*10-(Gic.won and Gic.t/60 or((Gic.left or 1)*9-math.min(9,Gic.t/60)))
end
gb.LADDER={1,1.3,1.7,2.2,3,4,6,8,12,16,24}
function gb.cliff(Hic,Iic,Jic)
local Kic
for Lic,Mic in ipairs(gb.LADDER)do
Kic=gb.run(Hic,Iic,{hpMul=Mic,layout=Jic})
if not Kic.won then
return Mic,Kic
end
end
return gb.LADDER[#gb.LADDER],Kic
end
gb.TEAM_FASTER,gb.TEAM_FASTER_S=0.05,15
function gb.teamFaster(Nic,Oic,Pic)
if Nic.infinite or Nic.timeLimit or type(Pic)~=DLe[2274]or not Pic.won or not tonumber(Pic.minutes)then
return nil
end
local Qic=gb.teamFrom(Oic,Nic.map)
local Ric=gb.run(Nic,Qic,{hpMul=1})
