return nil
end
local Sic=gb.run(Nic,Qic,{hpMul=1.3})
if not(Sic and Sic.won)then
return nil
end
local Tic,Uic=tonumber(Pic.minutes)*60,tonumber(Ric.t)or math.huge
if Uic<=Tic*(1-gb.TEAM_FASTER)and Tic-Uic>=gb.TEAM_FASTER_S then
return{mine=Tic,pick=Uic}
end
return nil
end
function gb.exam(Vic,Wic)
