function gb.lockTeam(Pjc,Qjc,Rjc)
local Sjc=table.clone(Pjc)
local Tjc={}
for Ujc,Vjc in ipairs(Sjc)do
Tjc[Vjc.unit_id]=true
end
local Wjc=N.session()
for Xjc in pairs(Rjc)do
if not Tjc[Xjc]then
local Yjc
for Zjc,_jc in ipairs({Qjc or{},(type(Qjc)==DLe[2274]and Qjc.rest)or{}})do
for akc,bkc in ipairs(_jc)do
if bkc.unit_id==Xjc then
Yjc=bkc
break
end
end
if Yjc then
break
end
end
if not Yjc and Wjc then
local ckc
for dkc,ekc in pairs(Wjc.profile_data.collection.owned_units)do
if ekc.unit_id==Xjc then
local fkc=Wjc.collection:get_unit_by_uuid(ekc.uuid)or ekc
local gkc,hkc=pcall(V.score,fkc)
hkc=gkc and tonumber(hkc)or 0
if not ckc or hkc>ckc then
Yjc,ckc=fkc,hkc
end
end
end
end
if Yjc then
local ikc
for jkc,kkc in ipairs(Sjc)do
if not Rjc[kkc.unit_id]and V.sameGroup(kkc.unit_id,Xjc)then
ikc=jkc
end
end
if not ikc and#Sjc<6 then
table.insert(Sjc,Yjc)
else
if not ikc then
local lkc=0
for mkc,nkc in ipairs(Sjc)do
if V.isFarm(nkc.unit_id)then
lkc=lkc+1
end
end
local okc
for pkc,qkc in ipairs(Sjc)do
if not Rjc[qkc.unit_id]and not(V.isFarm(qkc.unit_id)and lkc<=1)then
local rkc,skc=pcall(V.score,qkc)
skc=V.isFarm(qkc.unit_id)and math.huge or(rkc and tonumber(skc)or 0)
if not okc or skc<okc then
ikc,okc=pkc,skc
end
end
end
end
if ikc then
Sjc[ikc]=Yjc
end
end
Tjc[Xjc]=true
end
end
end
return Sjc
end
function gb.bestTeam(tkc,ukc,vkc,wkc)
local xkc=U.now()
