local Xkc=false
for Ykc,Zkc in ipairs(ykc)do
if V.sameGroup(Zkc.unit_id,Wkc.unit_id)then
Xkc=true
end
end
if not Xkc and(not Ukc or V.isFarm(Wkc.unit_id))then
local _kc=table.clone(ykc)
table.insert(_kc,Wkc)
local alc=gb.run(tkc,gb.teamFrom(_kc,tkc.map),{hpMul=Ekc})
local blc=gb.objective(alc)
