local hlc=table.clone(ykc)
hlc[elc]=glc
local ilc=gb.run(tkc,gb.teamFrom(hlc,tkc.map),{hpMul=Ekc})
local jlc=gb.objective(ilc)
if not dlc or jlc>dlc then
clc,dlc,Rkc=hlc,jlc,ilc
