if qlc then
local wlc,xlc={},U.now()
for ylc,zlc in ipairs(vkc.rest)do
if U.now()-xlc>5 then
break
end
local Alc=false
for Blc,Clc in ipairs(ykc)do
if V.sameGroup(Clc.unit_id,zlc.unit_id)then
Alc=true
end
end
if not Alc then
local Dlc=table.clone(ykc)
Dlc[qlc]=zlc
