local yoc=DLe[4269]..U.json(tostring(ooc))
for zoc= #woc,1,-1 do
if woc[zoc]:find(yoc,1,true)then
local Aoc=U.unjson(woc[zoc])
local Boc=type(Aoc)==DLe[2274]and type(Aoc.result)==DLe[2274]and Aoc.result.shares
if type(Boc)==DLe[2274]then
for Coc,Doc in pairs(Boc)do
