soc[Coc],toc[Coc]=(soc[Coc]or 0)+tonumber(Doc),(toc[Coc]or 0)+1
end
end
end
end
end
end)
for Eoc,Foc in pairs(soc)do
roc[Eoc]=Foc/toc[Eoc]
