local Fwc=tonumber(N.cur(DLe[2347]))or 0
local Gwc=jb.wallet()
for Hwc=1,ywc+zwc+4 do
local Iwc,Jwc,Kwc=jb.res(jb.data())
if Jwc+Kwc<=0 or Ewc>=2 then
break
end
local Lwc,Mwc
if Jwc>0 then
Lwc,Mwc=F.request(DLe[4413],DLe[4001])
