end
if bb.kind==DLe[2743]then
return string.format(DLe[4510],tostring(bb.ld._infinite_tower_floor or DLe[2525]),tostring(bb.ld._difficulty or DLe[1198]),tostring(bb.ld.name or bb.ld.map or DLe[2525]))
end
if bb.kind==DLe[2744]then
local cCc=type(bb.ld._tournament)==DLe[2274]and bb.ld._tournament or{}
return string.format(DLe[4511],tostring(cCc.tournament_id or DLe[2525]),W.tnWords({score=cCc.score_type,limit=tonumber(cCc.level_time_limit),traitless=cCc.traitless}))
end
return W.levelName(bb.ld.id or DLe[2525])..(bb.ld._difficulty and(DLe[3002]..bb.ld._difficulty..DLe[2955])or DLe[1193])
