function bb.buildPath()
bb.samples={}
local eCc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not eCc then
return
end
for fCc,gCc in pairs(eCc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[fCc.Name])then
local hCc={}
for iCc,jCc in ipairs(gCc.points or{})do
table.insert(hCc,jCc.part.Position)
end
local kCc=0
for lCc=2,#hCc do
kCc=kCc+(hCc[lCc]-hCc[lCc-1]).Magnitude
end
local mCc=0
for nCc=2,#hCc do
local oCc,pCc=hCc[nCc-1],hCc[nCc]
local qCc=(pCc-oCc).Magnitude
local rCc=math.max(1,math.floor(qCc/2))
for sCc=0,rCc-1 do
local tCc=oCc:Lerp(pCc,sCc/rCc)
table.insert(bb.samples,{pos=tCc,prog=(mCc+qCc*sCc/rCc)/math.max(1,kCc),lane=fCc.Name})
end
mCc=mCc+qCc
end
if hCc[#hCc]then
table.insert(bb.samples,{pos=hCc[#hCc],prog=1,lane=fCc.Name})
end
end
end
pcall(bb.readHidden,eCc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local uCc=tonumber(bb.ld and bb.ld._portal_lanes)
local vCc=gb.laneList(bb.samples)
if uCc and uCc>=1 and vCc and#vCc>uCc then
bb.laneWant=uCc
end
bb.laneTotal=vCc and#vCc or 1
bb.countLanes()
end
function bb.readHidden(wCc)
local xCc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(xCc)~=DLe[2274]or not next(xCc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local yCc
for zCc,ACc in pairs(wCc)do
if xCc[zCc.Name]and type(ACc.points)==DLe[2274]and#ACc.points>=2 then
local BCc={}
for CCc,DCc in ipairs(ACc.points)do
BCc[CCc]=U.flat(DCc.part.Position)
end
local ECc={}
for FCc,GCc in ipairs(bb.samples)do
local HCc=tostring(GCc.lane)
ECc[HCc]=ECc[HCc]or{}
table.insert(ECc[HCc],GCc)
end
local ICc,JCc
for KCc,LCc in pairs(ECc)do
local MCc=0
for NCc=1,#BCc,math.max(1,math.floor(#BCc/20))do
local OCc=math.huge
for PCc,QCc in ipairs(LCc)do
local RCc=(U.flat(QCc.pos)-BCc[NCc]).Magnitude
if RCc<OCc then
OCc=RCc
end
end
MCc=MCc+OCc
end
if not JCc or MCc<JCc then
ICc,JCc=KCc,MCc
end
end
local SCc,TCc,UCc,VCc,WCc,XCc={},nil,nil,nil,0,0
for YCc,ZCc in ipairs(BCc)do
local _Cc,aDc=nil,math.huge
for bDc,cDc in ipairs(ECc[ICc])do
local dDc=(U.flat(cDc.pos)-ZCc).Magnitude
if dDc<aDc then
aDc,_Cc=dDc,cDc.prog
end
end
XCc=math.max(XCc,aDc)
if UCc then
local eDc=_Cc-UCc
local fDc=(eDc>0.002 and 1)or(eDc< -0.002 and-1)or VCc
if VCc and fDc and fDc~=VCc then
table.insert(SCc,math.floor(UCc*1000+0.5)/1000)
end
VCc,WCc=fDc or VCc,WCc+math.abs(eDc)
else
TCc=_Cc
end
UCc=_Cc
if YCc%50==0 then
task.wait()
end
end
if UCc and XCc<=8 then
table.insert(SCc,math.floor(UCc*1000+0.5)/1000)
yCc=yCc or{}
yCc[zCc.Name]={from=math.floor((TCc or 0)*1000+0.5)/1000,len=math.floor(WCc*1000+0.5)/1000,turns=SCc,road=ICc}
end
end
end
if not yCc then
return
end
local gDc=bb.ld.map
P.maps[gDc]=P.maps[gDc]or{}
local hDc=P.maps[gDc].hidden
P.maps[gDc].hidden=yCc
if type(hDc)~=DLe[2274]then
for iDc,jDc in pairs(yCc)do
F.log(1,DLe[2962],string.format(DLe[4513],iDc,jDc.len,tostring(jDc.road),math.floor((#jDc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local kDc,lDc,mDc={},0,0
for nDc,oDc in ipairs(bb.samples)do
local pDc=tostring(oDc.lane)
if not kDc[pDc]then
lDc=lDc+1
end
kDc[pDc]=(kDc[pDc]or 0)+1
mDc=mDc+1
end
bb.laneCount={n=lDc,by=kDc,avg=lDc>0 and mDc/lDc or 1}
if lDc>=2 then
local qDc,rDc=pcall(gb.laneSep,bb.samples)
local sDc=P.maps[bb.mapKey()]
if qDc and rDc and type(sDc)==DLe[2274]then
sDc.sep=rDc
end
end
end
bb.LANE_WAIT=3
function bb.portalLanes()
if not bb.laneWant or bb.laneCut then
return true
end
if bb.planning then
return false
end
local tDc,uDc={},0
for vDc,wDc in ipairs(workspace._UNITS:GetChildren())do
local xDc=wDc:FindFirstChild(DLe[2346])
if xDc and xDc:FindFirstChild(DLe[4514])and xDc.player.Value==nil and xDc:FindFirstChild(DLe[4515])and wDc:FindFirstChild(DLe[3629])then
local yDc=tostring(xDc.lane.Value)
if not tDc[yDc]then
tDc[yDc]=true
uDc=uDc+1
end
end
end
if uDc==0 then
if U.now()-(bb.startT or U.now())>45 then
bb.laneWant=nil
F.log(1,DLe[2962],DLe[4516])
return true
end
return false
end
bb.laneFirst=bb.laneFirst or U.now()
if uDc<bb.laneWant and U.now()-bb.laneFirst<bb.LANE_WAIT then
return false
end
local zDc,ADc={},{}
for BDc,CDc in ipairs(bb.samples)do
if tDc[tostring(CDc.lane)]then
table.insert(zDc,CDc)
end
end
if#zDc==0 then
bb.laneWant=nil
return true
end
for DDc in pairs(tDc)do
table.insert(ADc,DDc)
end
table.sort(ADc)
bb.samples,bb.laneCut=zDc,table.concat(ADc,DLe[2604])
bb.countLanes()
local EDc,FDc=pcall(bb.buildCandidates)
if not EDc then
F.log(1,DLe[2283],DLe[4517]..tostring(FDc))
end
F.log(1,DLe[2962],string.format(DLe[4518],bb.laneWant,bb.laneCut))
if bb.info and O.simSpots and not bb.joinedMid and not bb.random and not bb.infinite and not bb.trialId then
bb.planning=U.now()
task.spawn(function()
local GDc,HDc=pcall(bb.planSpots)
bb.planning=nil
if not GDc then
F.log(1,DLe[2283],DLe[4519]..tostring(HDc))
end
end)
end
return true
end
function bb.buildWaves()
local IDc=bb.ld
local JDc=IDc and IDc._dungeon and type(IDc._override_waves)==DLe[2274]and IDc._override_waves or nil
local KDc=IDc and N.Waves[(JDc and JDc.template)or IDc.waves or IDc.id]
local LDc
if type(KDc)==DLe[2274]then
LDc=KDc.override_waves or KDc.waves
if not LDc and KDc.template and N.Waves[KDc.template]then
LDc=N.Waves[KDc.template].waves or N.Waves[KDc.template].override_waves
end
end
bb.waveList=U.list(LDc)
bb.infinite=IDc and(IDc._gamemode==DLe[2299]or IDc.infinite)and gb.unbound(IDc)or false
if bb.infinite then
bb.waveList={}
bb.total=math.max(30,math.floor(W.infReach(bb.key)+0.5))
return
end
bb.total=(IDc and type(IDc._dungeon)==DLe[2274]and 15)or tonumber(IDc and IDc._override_infinite_bound_waves)or gb.boundEnd(IDc,#bb.waveList,bb.key)or(#bb.waveList>0 and#bb.waveList)or 15
end
function bb.infExtend()
if bb.infinite and bb.wave()+5>bb.total then
bb.total=bb.wave()+10
end
end
function bb.infWave(MDc)
bb.infWaveAt=bb.infWaveAt or{}
bb.infWaveAt[MDc]=bb.infWaveAt[MDc]or U.now()
bb.infExtend()
local NDc=math.floor(tonumber(O.infLeaveWave)or 0)
if NDc>0 and MDc>=NDc and not bb.stopping and ab.partyRole()~=DLe[3957]and bb.kind~=DLe[2744]then
bb.stopping=true
F.log(1,DLe[2962],string.format(DLe[4520],MDc))
local ODc,PDc=pcall(bb.sellAll)
if not ODc then
F.log(1,DLe[2283],DLe[4521]..tostring(PDc))
end
end
if O.trainLeave and not bb.stopping then
local QDc,RDc=pcall(bb.trainLeave,MDc)
if not QDc then
F.log(1,DLe[2283],DLe[4522]..tostring(RDc))
end
end
if O.infiniteStop and not bb.stopping and ab.partyRole()~=DLe[3957]and bb.kind~=DLe[2744]then
local SDc,TDc=pcall(bb.infStop,MDc)
if not SDc then
F.log(1,DLe[2283],DLe[4523]..tostring(TDc))
end
end
local UDc=W.infTier(MDc-1)
if UDc<=0 or UDc==bb.infTierSeen then
return
end
bb.infTierSeen=UDc
task.delay(5,function()
if not F.alive then
return
end
local VDc=N.prof()
local WDc=VDc and VDc.daily_infinite_reward_claims and VDc.daily_infinite_reward_claims[bb.ld.id]
local XDc=type(WDc)==DLe[2274]and(tonumber(WDc.highest_claimed_wave)or 0)>=UDc and os.time()-(tonumber(WDc.highest_claim_time)or 0)<900
if XDc then
P.infLive=true
end
F.log(1,DLe[2962],string.format(DLe[4524],UDc,XDc and DLe[4525]or DLe[4526]))
end)
end
function bb.infStop(YDc)
local ZDc=0
for _Dc,aEc in ipairs(U.list(N.GS.DAILY_INFINITE_REWARDS))do
ZDc=math.max(ZDc,tonumber(aEc.wave)or 0)
end
if ZDc<=0 or YDc<=ZDc+1 then
return
end
local bEc=P.train.on
if bb.trainee and bEc and bEc.have+(bEc.got or 0)+(bb.trainTk or 0)<bEc.need then
return
end
if not ab.every(DLe[4527],60)then
return
end
local cEc=W.rec(bb.key)
local dEc=tonumber(cEc.timed)or 0
local eEc=W.INF_PAY
local fEc
if YDc>=(eEc.cap+eEc.less)/eEc.per then
fEc=0
else
local gEc=bb.infWaveAt or{}
local hEc,iEc=gEc[YDc],gEc[YDc-5]
if hEc and iEc and hEc>iEc then
fEc=eEc.per*5/((hEc-iEc)/60)
end
if not fEc then
fEc=(dEc>0 and(cEc.sec or 0)>0)and math.max(0.5,(cEc.gems or 0)/(cEc.sec/60))or 2.5
end
end
local jEc=pcall(W.pick)
local kEc
for lEc,mEc in ipairs(jEc and W.lastScored or{})do
if mEc.kind~=DLe[2299]and(not kEc or(mEc.score or 0)>(kEc.score or 0))then
kEc=mEc
end
end
if not kEc or(kEc.score or 0)<=fEc then
return
end
bb.stopping=true
F.log(1,DLe[2962],string.format(DLe[4528],YDc,fEc,kEc.score,kEc.label))
bb.sellAll()
end
function bb.trainLeave(nEc)
local oEc=P.train.on
if not(bb.infinite and bb.trainee and oEc)then
return
end
bb.trainCount()
local pEc=oEc.have+(oEc.got or 0)+(bb.trainTk or 0)
if pEc<oEc.need then
return
end
local qEc,rEc,sEc=pcall(W.infDaily,N.prof(),bb.ld.id,(W.infReach(bb.key)))
if qEc and(rEc or 0)>0 and sEc>0 and nEc<=sEc then
F.status(DLe[3594],string.format(DLe[4529],V.name(oEc.id),oEc.what,sEc))
return
end
bb.stopping=true
F.log(1,DLe[2962],string.format(DLe[4530],V.name(oEc.id),oEc.what,U.fmt(pEc),U.fmt(oEc.need),nEc))
bb.sellAll()
end
function bb.sellAll()
task.spawn(function()
local tEc={}
for uEc,vEc in ipairs(bb.mine or{})do
local wEc=vEc:FindFirstChild(DLe[2346])
local xEc=wEc and wEc:FindFirstChild(DLe[2667])and N.Units[wEc.id.Value]
if not(xEc and xEc.unsellable)then
table.insert(tEc,vEc)
end
end
local function yEc(zEc)
local AEc=zEc:FindFirstChild(DLe[2346])
return AEc and AEc:FindFirstChild(DLe[2667])and V.isFarm(AEc.id.Value)or false
end
table.sort(tEc,function(BEc,CEc)
return(yEc(BEc)and 1 or 0)<(yEc(CEc)and 1 or 0)
end)
local DEc={}
for EEc=1,2 do
local FEc={}
for GEc,HEc in ipairs(EEc==1 and tEc or DEc)do
if not F.alive or bb.finished then
return
end
if HEc.Parent and HEc.Parent.Name==DLe[4531]then
local IEc,JEc=F.request(DLe[2473],DLe[2365],HEc)
if JEc~=true then
table.insert(FEc,HEc)
end
task.wait(1.3)
end
end
DEc=FEc
end
if#DEc>0 then
local KEc={}
for LEc,MEc in ipairs(DEc)do
table.insert(KEc,MEc.Name)
end
F.log(1,DLe[2962],DLe[4532]..table.concat(KEc,DLe[2398])..DLe[4533])
end
end)
end
function bb.waveReward(NEc)
