function bb.scan()
local dFc,eFc={},{}
for fFc,gFc in ipairs({workspace._UNITS})do
for hFc,iFc in ipairs(gFc:GetChildren())do
local jFc=iFc:FindFirstChild(DLe[2346])
if jFc and jFc:FindFirstChild(DLe[4514])then
local kFc=jFc:FindFirstChild(DLe[4534])
local lFc=kFc and kFc.Value
local mFc=lFc and lFc:FindFirstChild(DLe[2346])
local nFc=N.Units[jFc.id.Value]
local oFc=lFc~=nil and nFc~=nil and(tonumber(nFc.cost)or 0)>=100 and(not mFc or(mFc:FindFirstChild(DLe[2667])and mFc.id.Value==jFc.id.Value))
if jFc.id.Value==DLe[4535]then
oFc=true
end
local pFc=(lFc~=nil and not oFc)or not jFc:FindFirstChild(DLe[2725])or not jFc:FindFirstChild(DLe[2377])or not jFc:FindFirstChild(DLe[2542])
if jFc.player.Value==M then
if nFc and nFc._defense then
pFc=true
end
if not pFc then
table.insert(eFc,iFc)
end
elseif jFc.player.Value==nil and iFc:FindFirstChild(DLe[3629])then
local qFc,rFc,sFc=bb.progressAt(iFc.HumanoidRootPart.Position)
local tFc=iFc:FindFirstChildOfClass(DLe[2683])
local uFc=tFc and tFc.Health or(jFc:FindFirstChild(DLe[3896])and jFc.health.Value)or 0
local vFc=jFc:FindFirstChild(DLe[4138])and tonumber(jFc.damage_reduction.Value)or 0
local wFc=bb.info and bb.info.cfgById[jFc.id.Value]
local xFc=jFc:FindFirstChild(DLe[4358])and(tonumber(jFc.Flying.Value)or 0)>0 or false
local yFc=jFc:FindFirstChild(DLe[4536])and(tonumber(jFc.Soaring.Value)or 0)>0 or false
local zFc=jFc:FindFirstChild(DLe[3089])and tonumber(jFc.shield.Value)or 0
local AFc=wFc and(tostring(wFc):find(DLe[3092])~=nil or gb.bossKeys(bb.info)[wFc]==true)or false
table.insert(dFc,{m=iFc,pos=iFc.HumanoidRootPart.Position,prog=qFc,lane=sFc,hp=uFc,red=vFc,fly=xFc,soar=yFc,sh=zFc,boss=AFc,uid=jFc.id.Value})
if tostring(jFc.id.Value):find(DLe[4537])then
pcall(bb.noteStar,iFc,tFc)
end
end
end
end
end
bb.enemies,bb.mine=dFc,eFc
pcall(function()
local BFc=bb.wave()
if BFc>0 and#dFc>0 then
local CFc=0
for DFc,EFc in ipairs(dFc)do
if(EFc.prog or 0)>CFc then
CFc=EFc.prog
end
end
bb.waveReach=bb.waveReach or{}
bb.waveReach[BFc]=math.max(bb.waveReach[BFc]or 0,CFc)
end
end)
if not bb.flyerSeen then
for FFc,GFc in ipairs(dFc)do
if GFc.fly then
bb.flyerSeen=math.max(1,bb.wave())
if not bb.random then
F.log(1,DLe[2962],string.format(DLe[4538],bb.flyerSeen))
end
break
end
end
end
if not bb.shieldSeen then
for HFc,IFc in ipairs(dFc)do
if(IFc.sh or 0)>0 then
bb.shieldSeen=true
local JFc=IFc.m._stats
F.log(1,DLe[2962],string.format(DLe[4539],bb.wave(),tostring(IFc.sh),tostring(JFc:FindFirstChild(DLe[4540])and JFc.max_shield.Value),tostring(JFc:FindFirstChild(DLe[2667])and JFc.id.Value),IFc.hp,tostring(bb.info and bb.info.shield)))
break
end
end
end
local KFc=bb.wave()
local LFc=0
local MFc,NFc,OFc=0,0,0
for PFc,QFc in ipairs(dFc)do
LFc=math.max(LFc,QFc.prog)
MFc=MFc+QFc.hp/math.max(0.1,1-QFc.red)
OFc=OFc+QFc.hp
end
bb.hpAliveRaw=OFc
for RFc,SFc in ipairs(eFc)do
local TFc=SFc._stats.id.Value
if not V.isFarm(TFc)and SFc._stats:FindFirstChild(DLe[2724])then
local UFc,VFc=pcall(bb.liveDps,SFc,TFc)
if UFc and VFc then
NFc=NFc+VFc
end
end
end
bb.hpAlive,bb.teamDps=MFc,NFc
bb.clearSec=MFc>0 and(NFc>0 and MFc/NFc or math.huge)or 0
bb.waveMax[KFc]=math.max(bb.waveMax[KFc]or 0,LFc)
bb.front=LFc
bb.pressure=math.max(bb.waveMax[KFc]or 0,bb.waveMax[KFc-1]or 0)
bb.depth=bb.coverage(eFc,dFc)
local WFc=U.now()
bb.aliveHist=bb.aliveHist or{}
table.insert(bb.aliveHist,{t=WFc,n= #dFc})
while bb.aliveHist[1]and WFc-bb.aliveHist[1].t>12 do
table.remove(bb.aliveHist,1)
end
local XFc=bb.aliveHist[1]
bb.piling= #dFc>=8 and XFc and WFc-XFc.t>=8 and#dFc>XFc.n+1 or false
if#dFc>=18 then
bb.piling=true
end
end
function bb.setupChecks()
bb.probe=Instance.new(DLe[4541])
bb.probe.Name=DLe[4542]
bb.probe.Anchored=true
bb.probe.CanCollide=false
bb.probe.CanTouch=false
bb.probe.CanQuery=false
