table.remove(sOc.wave,1)
end
sOc.at=os.time()
rOc.ways[bb.labWay]=sOc
rOc.at=os.time()
if not pOc and not bb.infinite and rOc.best and rOc.best==bb.labWay then
rOc.best=nil
local vOc,wOc=pcall(bb.labBetter,rOc,rOc.usual or bb.labParse(bb.labWay).style)
rOc.best=vOc and wOc or nil
