function bb.holdGain(acd,bcd)
if bb.random or not bcd or not bb.info then
return 0
end
local ccd=V.attackInfo(bcd.atk,bcd.range)
if(ccd.stun or 0)<=0 and(ccd.slowTime or 0)<=0 then
return 0
end
local dcd=0
for ecd,fcd in ipairs(bb.mine or{})do
local gcd=fcd._stats
local hcd=V.rows(gcd.id.Value)
local icd=hcd and hcd[math.min(gcd.upgrade.Value,hcd.max)]
local jcd=icd and icd.atk and V.attackInfo(icd.atk,icd.range)
if jcd and((jcd.stun or 0)>0 or(jcd.slowTime or 0)>0)then
dcd=dcd+1
end
end
local kcd,lcd=gb.mask(bb.info.map,V.range(acd.u,0)*(bb.info.rangeScale or 1)),0
for mcd=1,gb.BINS do
if kcd[mcd]then
lcd=lcd+1
end
end
local ncd=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
local ocd=(V.airFrom(acd.id)==0)and 1 or(1-(1-N.FLY_GROUND)*math.min(1,bb.info.flyChance or 0))
return eb.holdGain(ccd,bb.teamDps or 0,lcd/(math.max(0.1,ncd)*gb.BINS)*ocd,dcd)
end
