local Dkd=(bb.info and tonumber(bb.info.waveSec))or 20
local Ekd=math.max(1,tonumber(bb.incomeRate)or((((bb.coming and bb.coming[1]and bb.coming[1].reward)or 500)+(tonumber(bb.farmNow)or 0))/Dkd))
local Fkd=math.max(0,Ckd-rkd)/Ekd
local Gkd=(bb.teamDps or 0)/(1+U.clamp(tonumber(bb.buffLevel())or 0,0,2))/V.GRIF.need/(1+Fkd/(6*Dkd))
