mb.CARD_PICKS={DLe[1195],DLe[2292],DLe[2854],DLe[1197]}
function mb.cardPearls(tod,uod)
local vod=mb.pearlsFrom((tonumber(uod)or 0)+1,50)
local wod=0
for xod,yod in pairs(type(tod)==DLe[2274]and type(tod.effects)==DLe[2274]and tod.effects or{})do
if type(yod)==DLe[2274]and yod.type==DLe[2836]then
wod=wod+math.abs(tonumber(yod.amount)or 0)*vod
end
end
return wod
end
function mb.cardLuck(zod)
local Aod=0
for Bod,Cod in pairs(type(zod)==DLe[2274]and type(zod.effects)==DLe[2274]and zod.effects or{})do
if type(Cod)==DLe[2274]and Cod.type==DLe[2839]then
Aod=Aod+(tonumber(Cod.amount)or 0)
end
