function bb.huntChoose(Dod,Eod)
bb.fhP=bb.fhP or 1
local Fod=mb.floor()
local God=(bb.pressure or 0)>=O.safeReach or(bb.depth and bb.depth.leak)
local Hod=mb.weatherStrength(mb.weatherNow())
local Iod=table.find(mb.CARD_PICKS,O.huntCards)and O.huntCards or DLe[1197]
local Jod,Kod,Lod,Mod
local Nod={}
bb.fhFactors={}
for Ood,Pod in pairs(Dod)do
local Qod,Rod=1,{}
for Sod,Tod in pairs(type(Pod)==DLe[2274]and Pod.effects or{})do
if type(Tod)==DLe[2274]then
local Uod=bb.rogueEffect(Tod)
Qod=Qod*Uod
table.insert(Rod,bb.effectText(Tod))
end
end
if type(Pod)==DLe[2274]and Pod.weather then
Qod=Qod*mb.weatherStrength(Pod.weather)/math.max(0.05,Hod)
end
if type(Pod)==DLe[2274]and(Pod.title or Pod.name)then
bb.fhFactors[tostring(Pod.title or Pod.name):lower():gsub(DLe[4930],DLe[1193])]=Qod
end
local Vod=type(Pod)==DLe[2274]and mb.cardGems(Pod,Eod)or 0
local Wod=Qod>=1 or(bb.fhP*Qod>=Fod and not God)
local Xod=math.log(math.max(0.05,Qod))
local Yod=Xod*mb.STRENGTH_GEMS+(Wod and Vod or-1000)
local Zod=mb.cardLuck(Pod)
if Iod==DLe[1195]and Wod and Zod>0 then
Yod=2e6+Zod*1e4+Vod
elseif Iod==DLe[2292]and Wod then
Yod=1e6+mb.cardPearls(Pod,Eod)*10+Vod+Xod
elseif Iod==DLe[2854]then
Yod=Xod*1e6+Vod
end
if not Kod or Yod>Kod then
Jod,Kod,Lod,Mod=Ood,Yod,Qod,Vod
end
table.insert(Nod,string.format(DLe[4931],tostring(Ood),tostring(type(Pod)==DLe[2274]and Pod.title or DLe[2525]),(type(Pod)==DLe[2274]and Pod.weather)and(DLe[3002]..tostring(Pod.weather)..DLe[2955])or DLe[1193],tostring(type(Pod)==DLe[2274]and Pod.option_type or DLe[2525]),Qod,math.floor(Vod+0.5),table.concat(Rod,DLe[2926])))
end
return Jod,Lod,Mod,Nod,Fod,God,Iod
end
