function bb.huntWeakText()
local Epd=type(P.hunt)==DLe[2274]and P.hunt.runs or{}
if#Epd<bb.HUNT_WEAK_RUNS then
return nil
end
local Fpd,Gpd,Hpd=0,0,{}
for Ipd=1,bb.HUNT_WEAK_RUNS do
local Jpd=Epd[Ipd]
if type(Jpd)~=DLe[2274]or Jpd.won then
return nil
end
Fpd,Gpd=Fpd+(tonumber(Jpd.pearls)or 0),Gpd+(tonumber(Jpd.sec)or 0)
table.insert(Hpd,tonumber(Jpd.wave)or 0)
end
if Gpd<=0 then
return nil
end
table.sort(Hpd)
local Kpd=Hpd[math.ceil(#Hpd/2)]
local Lpd=Fpd/Gpd*60*(tonumber(O.pearlValue)or 0.35)
local Mpd={string.format(DLe[4955],bb.HUNT_WEAK_RUNS,Kpd,Lpd)}
local Npd
for Opd,Ppd in ipairs(W.lastScored or{})do
if Ppd.kind~=DLe[2297]and(tonumber(Ppd.score)or 0)>0 then
Npd=Ppd
break
end
end
if Npd then
table.insert(Mpd,string.format(DLe[4956],tostring(Npd.label),Npd.score))
end
