for Rpd,Spd in ipairs(bb.HUNT_WEAK_KINDS)do
if O[Spd]==false then
Qpd=Qpd+1
end
end
if W.onlyOn()then
table.insert(Mpd,DLe[4957])
elseif Qpd>=4 then
