function bb.rogueShare(qqd)
if not qqd then
return 0.5
end
local rqd=tostring(qqd):gsub(DLe[4214],DLe[1193])
local sqd,tqd=0,0
for uqd,vqd in ipairs(bb.mine or{})do
local wqd=vqd._stats.id.Value
if not V.isFarm(wqd)then
local xqd,yqd=pcall(bb.liveDps,vqd,wqd)
yqd=xqd and yqd or 0
local zqd=V.types(wqd)
sqd=sqd+yqd
if zqd[rqd]or zqd[rqd..DLe[2493]]then
tqd=tqd+yqd
end
end
end
local Aqd=0
for Bqd,Cqd in ipairs(bb.mine or{})do
if not V.isFarm(Cqd._stats.id.Value)then
Aqd=Aqd+1
end
end
local Dqd=Aqd/(Aqd+4)
return Dqd*(sqd>0 and tqd/sqd or 0.5)+(1-Dqd)*0.5
end
function bb.resistOf(Eqd)
local Fqd=V.types(Eqd)
local Gqd=0
for Hqd,Iqd in pairs(bb.fhResist or{})do
local Jqd=tostring(Hqd):gsub(DLe[4214],DLe[1193])
if Fqd[Jqd]or Fqd[Jqd..DLe[2493]]then
Gqd=math.max(Gqd,Iqd/100)
end
end
return math.min(0.95,Gqd)
end
function bb.rogueEffect(Kqd)
local Lqd,Mqd,Nqd=Kqd.type,tonumber(Kqd.amount)or 0,tostring(Kqd.stat or DLe[1193])
if Lqd==DLe[2836]then
return 1,math.abs(Mqd)
end
if Lqd==DLe[4341]or Lqd==DLe[4346]or Lqd==DLe[4342]then
if Nqd==DLe[2724]then
return math.max(0.3,1+Mqd),0
end
if Nqd==DLe[2542]then
return math.max(0.5,1+Mqd/2),0
end
if Nqd:find(DLe[3084])then
return 1/math.max(0.3,1+Mqd),0
end
return 1,0
end
if Lqd==DLe[4962]then
if Nqd==DLe[2724]then
return math.max(0.3,Mqd),0
end
if Nqd==DLe[2542]then
return math.max(0.5,1+(Mqd-1)/2),0
end
if Nqd:find(DLe[3084])then
return 1/math.max(0.3,Mqd),0
end
return 1,0
end
if Lqd==DLe[4348]then
return 1+Mqd/3,0
end
if Lqd==DLe[4354]then
return 1/math.max(0.3,1+Mqd),0
end
if Lqd==DLe[4963]then
return math.max(0.2,1-bb.rogueShare(Kqd.damage_type)*(1-100/(100+Mqd))),0
end
if Lqd==DLe[4964]then
return 1+bb.rogueShare(Kqd.damage_type)*Mqd,0
end
if Lqd==DLe[4965]then
return math.max(0.5,1-Mqd*0.5),0
end
if Lqd==DLe[4966]then
return math.max(0.5,1-Mqd*0.2),0
end
if Lqd==DLe[4967]then
return 1+Mqd*0.1,0
end
if Lqd==DLe[4968]then
return 1/math.max(0.3,1+Mqd*0.5),0
end
if Lqd==DLe[4969]then
return math.max(0.5,1-Mqd*0.1),0
end
if Lqd==DLe[4349]then
return 1/math.max(0.3,1+Mqd),0
end
if Lqd==DLe[4355]then
return math.max(0.3,1-Mqd*20),0
end
if Lqd==DLe[4356]then
return math.max(0.5,1-Mqd*0.03),0
end
if Lqd==DLe[4970]then
return 0.95,0
end
if Lqd==DLe[4357]then
return math.max(0.5,1-Mqd),0
end
if Lqd==DLe[4971]then
return 1+math.min(0.3,Mqd/40000),0
end
if Lqd==DLe[4350]then
return 1/math.max(0.3,1+Mqd/2),0
end
if Lqd==DLe[4972]then
return 0.8,0
end
if Lqd==DLe[4973]then
local Oqd=math.max(1,math.abs(Mqd))*math.max(1,math.abs(tonumber(Kqd.tier)or 1))
return Kqd._type==DLe[4974]and 1.1^Oqd or 0.8^Oqd,0
end
return 1,0
end
function bb.effectText(Pqd)
return string.format(DLe[4975],tostring(Pqd.type),Pqd.stat and(DLe[2876]..tostring(Pqd.stat))or DLe[1193],tostring(Pqd.amount))
end
function bb.learn()
local Qqd=bb.calRun and bb.calRun.potBy
if type(Qqd)~=DLe[2274]then
return
end
pcall(bb.sampleHelpers,true)
local Rqd={}
for Sqd,Tqd in pairs(bb.ownDealt or{})do
if not V.isFarm(Tqd.id)then
Rqd[Tqd.id]=(Rqd[Tqd.id]or 0)+(tonumber(Tqd.v)or 0)
end
end
for Uqd,Vqd in pairs(bb.helperDealt or{})do
if Vqd.owner and V.SUMMONER[Vqd.owner]and not V.droneHelper(Vqd)then
Rqd[Vqd.owner]=(Rqd[Vqd.owner]or 0)+(tonumber(Vqd.v)or 0)
end
end
local Wqd=type(bb.calRun.potExp)==DLe[2274]and bb.calRun.potExp or{}
local Xqd,Yqd=0,0
local Zqd={}
for _qd,ard in pairs(Qqd)do
if ard>0 then
Xqd,Yqd=Xqd+(Rqd[_qd]or 0),Yqd+ard
local brd=tonumber(Wqd[_qd])or ard
if brd>0 then
table.insert(Zqd,{id=_qd,r=(Rqd[_qd]or 0)/brd,w=brd})
end
end
end
if Xqd<=0 or Yqd<=0 then
return
end
table.sort(Zqd,function(crd,drd)
return crd.r<drd.r
end)
local function erd(frd)
local grd,hrd=0,0
for ird,jrd in ipairs(Zqd)do
if jrd.id~=frd then
grd=grd+jrd.w
end
end
if grd<=0 then
return nil
end
for krd,lrd in ipairs(Zqd)do
if lrd.id~=frd then
hrd=hrd+lrd.w
if hrd>=grd/2 then
return lrd.r
end
end
end
end
bb.lastEff={}
for mrd,nrd in pairs(Qqd)do
local ord=erd(mrd)
if nrd>0 and nrd/Yqd>0.02 and ord and ord>0 then
local prd=P.learn[mrd]or{eff=1,n=0,v=6}
V.learnUp(mrd,prd)
local qrd=math.max(0.02,0.25*math.sqrt(30/(30+prd.n)))
local rrd=U.clamp(((Rqd[mrd]or 0)/nrd)/ord,0.2,6)
bb.lastEff[mrd]=math.floor(rrd*1000+0.5)/1000
prd.eff=prd.eff+(rrd-prd.eff)*qrd
prd.n=prd.n+1
P.learn[mrd]=prd
end
end
local srd=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if srd and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==DLe[2274]and P.mapLearn or{}
local trd=type(P.mapLearn[srd])==DLe[2274]and P.mapLearn[srd]or{}
for urd,vrd in pairs(bb.lastEff)do
local wrd=type(trd[urd])==DLe[2274]and trd[urd]or{eff=vrd,n=0,v=6}
if(tonumber(wrd.v)or 0)<4 then
wrd.eff,wrd.v=(tonumber(wrd.eff)or vrd)*V.secRescale(urd),4
end
if(tonumber(wrd.v)or 0)<5 then
wrd.eff,wrd.v=(tonumber(wrd.eff)or vrd)*(V.sumRescale(urd)or 1),5
end
if(tonumber(wrd.v)or 0)<6 then
wrd.eff,wrd.v=(tonumber(wrd.eff)or vrd)*(1-(V.SUMMONER[urd]and V.SUMMONER[urd].droneShare or 0)),6
end
local xrd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(wrd.n)or 0))))
wrd.eff=(tonumber(wrd.n)or 0)==0 and vrd or((tonumber(wrd.eff)or vrd)+(vrd-(tonumber(wrd.eff)or vrd))*xrd)
wrd.n=(tonumber(wrd.n)or 0)+1
trd[urd]=wrd
end
trd._at=os.time()
P.mapLearn[srd]=trd
if U.count(P.mapLearn)>80 then
local yrd,zrd
for Ard,Brd in pairs(P.mapLearn)do
if not zrd or(tonumber(Brd._at)or 0)<zrd then
yrd,zrd=Ard,tonumber(Brd._at)or 0
end
end
P.mapLearn[yrd]=nil
end
end
end
function bb.randomTeam()
local Crd=N.session()
local Drd=Crd and Crd.collection.temporary_units or{}
local Erd,Frd={},{}
local function Grd(Hrd,Ird,Jrd)
local Krd=Hrd and Drd[Hrd]
if Krd and N.Units[Krd.unit_id]and not Frd[Hrd]then
Frd[Hrd]=true
