local Ywd=V.name(Iwd._stats.id.Value)
if bb.money()>=Xwd then
local Zwd=Twd and F.request(DLe[5050],DLe[5051],Twd,Iwd)or(not Twd and F.request(DLe[2473],DLe[2365],Iwd))
if Zwd then
F.log(1,DLe[4555],string.format(DLe[5052],Ywd,Twd and DLe[5053]or DLe[1193],V.name(Bwd.id)))
bb.roomSoldAt=U.now()
