function bb.refund()
local exd=N.session()
if not(bb.random and exd)or bb.spellBusy or bb.roomPlan or not ab.every(DLe[5057],20)then
return
end
local fxd
for gxd,hxd in pairs(exd.ingame_spells or{})do
if hxd==DLe[5044]then
fxd=gxd
end
end
if not fxd then
return
end
local ixd=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local jxd=bb.bestRate or 0
if ixd or jxd<=0 then
return
end
local kxd=bb.wave()
local lxd=math.max(0,(bb.total or 30)-kxd)
local mxd=bb.mergePlan
local nxd=bb.airLow()
local oxd,pxd,qxd
for rxd,sxd in ipairs(bb.mine)do
local txd=sxd._stats
local uxd=txd.id.Value
local vxd=N.Units[uxd]
local wxd=txd:FindFirstChild(DLe[4557])and tonumber(txd.total_spent.Value)or 0
if vxd and not vxd.unsellable and wxd>0 and not V.allyBuff(uxd)and not V.idol(uxd)and not(mxd and mxd.id==uxd)then
local xxd,yxd
if V.isFarm(uxd)then
local zxd=txd:FindFirstChild(DLe[2394])and tonumber(txd.farm_amount.Value)or 0
local Axd=zxd*lxd
if wxd>Axd*1.2 then
xxd=(wxd-Axd)*jxd
yxd=string.format(DLe[5058],U.fmt(Axd),U.fmt(wxd))
end
elseif kxd>=10 and lxd>2 and wxd>=5000 and(bb.upRate[sxd]or 0)<jxd/3 and bb.progressAt(sxd:GetPivot().Position)<0.8 and not(nxd and bb.canAir(sxd))then
local Bxd,Cxd=pcall(bb.liveDps,sxd,uxd)
Cxd=Bxd and Cxd or math.huge
if wxd*jxd>3*Cxd and Cxd<0.1*(bb.teamDps or 0)then
xxd=wxd*jxd-Cxd
yxd=string.format(DLe[5059],U.fmt(wxd))
end
end
if xxd and(not pxd or xxd>pxd)then
oxd,pxd,qxd=sxd,xxd,yxd
end
end
end
if not oxd then
return
end
bb.spellBusy=true
task.spawn(function()
local Dxd=V.name(oxd._stats.id.Value)
local Exd=F.request(DLe[5050],DLe[5051],fxd,oxd)
task.wait(1.5)
if Exd and(N.session().ingame_spells or{})[fxd]~=DLe[5044]then
bb.refunds=(bb.refunds or 0)+1
F.log(1,DLe[5030],string.format(DLe[5060],Dxd,qxd))
F.status(DLe[4913],DLe[5061]..Dxd)
else
F.backoff(DLe[5050],15)
F.log(2,DLe[5030],DLe[5062]..Dxd)
end
bb.spellBusy=false
end)
end
bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(Fxd,Gxd)
local Hxd=(Gxd.t or 0)-(Fxd.t or 0)
if Hxd<bb.BASE_WIN-1 then
return false
end
local Ixd=((tonumber(Fxd.base)or 0)-(tonumber(Gxd.base)or 0))/Hxd
if Ixd<=0 or(tonumber(Gxd.base)or 0)<=0 then
return false
end
local Jxd=Gxd.base/Ixd
local Kxd,Lxd=0,0
local Mxd,Nxd=Fxd.foes or{},Gxd.foes or{}
for Oxd,Pxd in pairs(Nxd)do
if Pxd.prog>=bb.BASE_END then
Kxd=Kxd+Pxd.hp
local Qxd=Mxd[Oxd]
if Qxd then
Lxd=Lxd+math.max(0,Qxd.hp-Pxd.hp)
end
end
end
for Rxd,Sxd in pairs(Mxd)do
if Sxd.prog>=bb.BASE_END and not Nxd[Rxd]then
Lxd=Lxd+Sxd.hp
end
end
if Kxd<=0 then
return false
end
local Txd=Lxd/Hxd
local Uxd=Txd>0 and Kxd/Txd or math.huge
local Vxd={baseTime=Jxd,loss=Ixd,atEnd=Kxd,rate=Txd,killTime=Uxd}
return Jxd<bb.BASE_SOON and Uxd>Jxd*bb.BASE_MARGIN,Vxd
end
