bb.LEAK_WIN,bb.LEAK_SOON,bb.LEAK_MIN,bb.LEAK_MARGIN,bb.LEAK_AHEAD=3,12,3,1.5,6
function bb.leakAhead(uyd)
local vyd=0
local wyd=U.flat(uyd.pos)
for xyd,yyd in ipairs(bb.mine or{})do
local zyd=yyd:FindFirstChild(DLe[2346])
local Ayd=zyd and zyd:FindFirstChild(DLe[2667])
local Byd=zyd and zyd:FindFirstChild(DLe[2542])
if Ayd and Byd and not V.isFarm(Ayd.Value)and not V.allyBuff(Ayd.Value)then
local Cyd,Dyd=U.flat(yyd:GetPivot().Position),Byd.Value
if(not uyd.fly or bb.canAir(yyd))and(Cyd-wyd).Magnitude>Dyd then
for Eyd,Fyd in ipairs(bb.samples or{})do
if Fyd.prog>uyd.prog and(U.flat(Fyd.pos)-Cyd).Magnitude<=Dyd then
vyd=vyd+1
break
end
end
end
end
end
return vyd
end
function bb.leakStep(Gyd)
if not Gyd then
if bb.kind~=DLe[2300]or bb.bailed or O.bailOut==false or bb.random or bb.infinite then
return
end
end
local Hyd=tostring(P.dg.room and P.dg.room.seed)
P.dg.bails=type(P.dg.bails)==DLe[2274]and P.dg.bails or{}
if not Gyd and(tonumber(P.dg.bails[Hyd])or 0)>=bb.BAIL_MAX then
return
end
local Iyd=workspace:FindFirstChild(DLe[5075])and workspace._BASES:FindFirstChild(DLe[4514])
local Jyd=Iyd and Iyd:FindFirstChild(DLe[4773])and Iyd.base:FindFirstChild(DLe[4774])
local Kyd=Jyd and Jyd:FindFirstChildOfClass(DLe[2683])
if not Kyd or Kyd.Health<=0 then
return
end
local Lyd=(bb.info and tonumber(bb.info.baseRel))or gb.PRIOR.baseRel
local Myd=U.now()
bb.leakTrack=bb.leakTrack or{}
local Nyd=bb.leakTrack
local Oyd,Pyd={},nil
for Qyd,Ryd in ipairs(bb.enemies or{})do
if Ryd.m then
Oyd[Ryd.m]=true
local Syd,Tyd=tonumber(Ryd.hp)or 0,tonumber(Ryd.prog)or 0
local Uyd=Nyd[Ryd.m]
if not Uyd then
Nyd[Ryd.m]={t=Myd,hp=Syd,prog=Tyd}
else
if Myd-Uyd.t>=bb.LEAK_WIN then
Uyd.pace,Uyd.net=(Tyd-Uyd.prog)/(Myd-Uyd.t),(Uyd.hp-Syd)/(Myd-Uyd.t)
Uyd.t,Uyd.hp,Uyd.prog=Myd,Syd,Tyd
end
if Uyd.pace and Uyd.pace>0 and Syd>0 then
local Vyd=(1-Tyd)/Uyd.pace
local Wyd=math.max(0,Uyd.net or 0)
local Xyd=Syd-Wyd*Vyd
if Xyd>0 and Vyd<=bb.LEAK_SOON and Vyd>=bb.LEAK_MIN then
local Yyd=Ryd.m:FindFirstChildOfClass(DLe[2683])
local Zyd=Kyd.Health/math.max(1,Lyd*(Yyd and Yyd.MaxHealth or Syd))
local _yd=Wyd>0 and Xyd/Wyd or math.huge
if _yd>Zyd*bb.LEAK_MARGIN and(Vyd<=bb.LEAK_AHEAD or bb.leakAhead(Ryd)==0)and(not Pyd or Vyd<Pyd.left)then
Pyd={left=Vyd,arriving=Xyd,net=Wyd,baseTime=Zyd,hp=Syd}
end
end
end
end
end
end
for azd in pairs(Nyd)do
if not Oyd[azd]then
Nyd[azd]=nil
end
end
if Gyd then
return Pyd~=nil,Pyd
end
if not Pyd then
return
end
bb.bailNote(Hyd,DLe[5069])
F.log(1,DLe[2962],string.format(DLe[5078],bb.wave(),tonumber(bb.total)or 0,math.floor(Pyd.left+0.5),U.fmt(Pyd.hp),U.fmt(Pyd.arriving),U.fmt(Pyd.net),Pyd.baseTime))
pcall(F.saveNow)
bb.toLobby(DLe[5077])
end
