function bb.allPast(bzd)
local czd={}
for dzd,ezd in ipairs(bb.mine or{})do
local fzd=ezd._stats
local gzd=fzd.id.Value
if not V.isFarm(gzd)and not V.allyBuff(gzd)and fzd:FindFirstChild(DLe[2542])then
local hzd=tonumber(fzd.range.Value)or 0
local izd=bb.coverMax[ezd]
if not(izd and izd.r==hzd)then
local jzd,kzd=U.flat(ezd:GetPivot().Position),-1
for lzd,mzd in ipairs(bb.samples or{})do
if mzd.prog>kzd and(U.flat(mzd.pos)-jzd).Magnitude<=hzd then
kzd=mzd.prog
end
end
izd={r=hzd,far=kzd}
bb.coverMax[ezd]=izd
end
table.insert(czd,{far=izd.far,air=bb.canAir(ezd)})
end
end
if#czd==0 then
return false
end
for nzd,ozd in ipairs(bzd)do
for pzd,qzd in ipairs(czd)do
if(not ozd.fly or qzd.air)and qzd.far>=(tonumber(ozd.prog)or 0)then
return false
end
end
end
return true
end
function bb.fbTick()
local rzd=bb.info and bb.info.final
if not(rzd and rzd.cfg)then
return
end
local szd=type(bb.info.configs)==DLe[2274]and bb.info.configs[rzd.cfg]
local tzd=type(szd)==DLe[2274]and szd.unit_id or rzd.cfg
local uzd
for vzd,wzd in ipairs(bb.enemies or{})do
local xzd=wzd.m and wzd.m:FindFirstChild(DLe[2346])
if xzd and xzd:FindFirstChild(DLe[2667])and xzd.id.Value==tzd then
uzd=wzd
break
end
end
local yzd=bb.fb
if not uzd then
if yzd and not yzd.gone then
yzd.gone=U.now()
end
return
end
local zzd=uzd.m:FindFirstChildOfClass(DLe[2683])
local Azd=(zzd and zzd.MaxHealth>0)and zzd.MaxHealth or uzd.hp
local Bzd=(N.Units[tzd]and N.Units[tzd].name)or tzd
if not yzd or yzd.m~=uzd.m then
yzd={m=uzd.m,id=tzd,name=Bzd,wave=bb.wave(),t0=U.now(),max=Azd,low=1,assassin=rzd.assassin,beatAt=tonumber(rzd.beatAt)or 0.5,walk=rzd.walk}
bb.fb=yzd
if rzd.assassin then
F.log(1,DLe[2962],string.format(DLe[5079],Bzd,yzd.wave,U.fmt(Azd),math.floor(yzd.beatAt*100+0.5)))
end
end
yzd.e=uzd
yzd.share=Azd>0 and uzd.hp/Azd or 1
yzd.low=math.min(yzd.low,yzd.share)
local Czd,Dzd=pcall(N.PATH.get_unit_path_progress,uzd.m)
yzd.gp=Czd and tonumber(Dzd)or nil
if yzd.assassin and not yzd.beaten and yzd.share<=yzd.beatAt+0.005 then
yzd.beaten=U.now()
F.log(1,DLe[2962],string.format(DLe[5080],Bzd,math.floor(yzd.share*100+0.5)))
end
if#(bb.enemies or{})==1 and bb.total and bb.wave()>=bb.total then
yzd.aloneT=yzd.aloneT or U.now()
yzd.alone=math.max(yzd.alone or 0,U.now()-yzd.aloneT)
else
yzd.aloneT=nil
end
end
function bb.fbEnd(Ezd)
local Fzd=bb.fb
if not Fzd then
return nil
