end
end
local gEd={}
for hEd,iEd in ipairs(bb.team or{})do
if iEd.hand then
gEd[iEd.id]=true
end
end
local jEd={}
for kEd,lEd in pairs(ZDd)do
table.sort(lEd,function(mEd,nEd)
if mEd.dps~=nEd.dps then
return mEd.dps>nEd.dps
end
return mEd.lvl>nEd.lvl
end)
table.insert(jEd,{id=kEd,dps=lEd[1].dps*bb.airBoost(lEd[1].m)*bb.reach(lEd[1].m)})
end
table.sort(jEd,function(oEd,pEd)
return oEd.dps>pEd.dps
