for qEd=1,math.min(3,#jEd)do
bb.mergeIds[jEd[qEd].id]=true
end
local rEd
for sEd,tEd in pairs(ZDd)do
local uEd=table.clone(tEd)
table.sort(uEd,function(vEd,wEd)
if vEd.lvl~=wEd.lvl then
return vEd.lvl<wEd.lvl
end
return vEd.dps<wEd.dps
end)
for xEd,yEd in ipairs(uEd)do
