local HEd,IEd,JEd=0,0,nil
for KEd,LEd in ipairs(tEd)do
if LEd~=EEd and(U.flat(LEd.m:GetPivot().Position)-FEd).Magnitude<=GEd then
HEd,IEd=HEd+LEd.dps,IEd+1
if not JEd or LEd.dps>JEd.dps then
JEd=LEd
