end
CEd=CEd or tEd[1]
local MEd=CEd.dps*bb.airBoost(CEd.m)*bb.reach(CEd.m)*(sEd==bb.planId and 2 or 1)
if(bb.mergeIds[sEd]or sEd==bb.planId)and(zEd or gEd[sEd])and(not rEd or MEd>rEd.score)then
rEd={id=sEd,top=CEd,fresh=zEd,near=AEd or 0,n=BEd or 0,coming=gEd[sEd],score=MEd}
end
end
bb.planId,bb.freshM=rEd and rEd.id,rEd and rEd.fresh and rEd.fresh.m
bb.mergeHeldAt=(WDd and rEd and rEd.fresh)and(bb.mergeHeldAt or bb.wave())or nil
if not rEd then
return F.status(DLe[5009],DLe[5107])
end
local NEd,OEd=bb.wave(),(bb.total or 30)-bb.wave()
local PEd=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local QEd=rEd.fresh
local REd=not PEd and OEd>3
rEd.waits=QEd and QEd.lvl<=rEd.top.lvl and rEd.top.lvl<rEd.top.max and REd or false
local SEd=(not QEd or QEd.lvl>=rEd.top.lvl)and rEd.coming and REd
local TEd=bb.cloneCard and rEd.top.lvl>=rEd.top.max and REd
local UEd=QEd and QEd.lvl>rEd.top.lvl and rEd.near<0.3*QEd.dps
rEd.ready=WDd and QEd~=nil and not UEd and(not(rEd.waits or SEd or TEd)or NEd-(bb.mergeHeldAt or NEd)>=5)
bb.holdNoCardAt=(rEd.waits and not WDd)and(bb.holdNoCardAt or NEd)or nil
rEd.hold=rEd.waits and(WDd or NEd-(bb.holdNoCardAt or NEd)<4)
bb.mergePlan=rEd
F.status(DLe[5009],QEd and string.format(DLe[5108],V.name(rEd.id),rEd.n,rEd.n==1 and DLe[5109]or DLe[5110],QEd.lvl,rEd.ready and DLe[5111]or(WDd and DLe[5112]or DLe[5113]))or string.format(DLe[5114],V.name(rEd.id)))
end
function bb.mergeHold(VEd)
