end
local hGd=bb.money()
local iGd=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local jGd,kGd,lGd
for mGd,nGd in ipairs(bb.mine)do
local oGd=nGd._stats.id.Value
if not V.isFarm(oGd)and not V.allyBuff(oGd)and oGd~=DLe[4535]then
local pGd,qGd=pcall(bb.liveDps,nGd,oGd)
local rGd=pGd and qGd and qGd*bb.airBoost(nGd)*bb.reach(nGd)
