function bb.trainCount()
local bHd=P.train.on
if not(bHd and bb.trainee)then
return
end
local cHd=0
for dHd,eHd in ipairs(bb.mine)do
local fHd=eHd._stats
local gHd=fHd:FindFirstChild(DLe[2666])and fHd.uuid.Value
local hHd=gHd==bb.trainee and fHd:FindFirstChild(bHd.what==DLe[2945]and DLe[5138]or DLe[2679])
if hHd then
cHd=cHd+(tonumber(hHd.Value)or 0)
end
end
bb.trainTk=math.max(bb.trainTk or 0,cHd)
F.status(DLe[3594],string.format(DLe[5139],V.name(bHd.id),bb.trainTk,bHd.what,U.fmt(bHd.have+(bHd.got or 0)+bb.trainTk),U.fmt(bHd.need)))
end
function bb.trainDone(iHd,jHd)
local kHd=P.train.on
if not(kHd and bb.trainee)then
return
end
bb.trainCount()
local lHd=bb.trainTk or 0
kHd.got=(kHd.got or 0)+lHd
local mHd=P.trainSim[iHd]and tonumber(P.trainSim[iHd].tk)
if not bb.joinedMid then
local nHd=P.train.real[iHd]or{n=0,sum=0}
nHd.n,nHd.sum=nHd.n+1,nHd.sum+lHd
P.train.real[iHd]=nHd
if mHd and mHd>0 then
local oHd=P.train.cal
oHd.real,oHd.sim,oHd.n=(oHd.real or 0)+lHd,(oHd.sim or 0)+mHd,(oHd.n or 0)+1
end
end
table.insert(P.train.log,1,{key=iHd,got=lHd,won=jHd,at=os.time()})
while#P.train.log>20 do
table.remove(P.train.log)
end
F.log(1,DLe[3587],string.format(DLe[5140],V.name(kHd.id),lHd,kHd.what,jHd and DLe[3060]or DLe[3061],mHd and string.format(DLe[5141],mHd)or DLe[1193],U.fmt(ib.realHave(kHd)),U.fmt(kHd.need)))
if not jHd then
P.train.bad[iHd]=os.time()+3600
F.log(1,DLe[3587],DLe[5142])
